'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["et"]={"g-flurpruefung":["Mida sisaldab visuaalne ja funktsionaalne kontroll enne tööle asumist?","Enne päeva esimest missiooni.","Kontrollige ainult kütusetaset ja sõiduki värvi.","Kontrollige pidureid, rooli, kahvleid, rehve ja turvaseadmeid vastavalt kasutusjuhendile.","Tehke proovisõit tõstetud koormaga.","Igapäevane ülevaatus hõlmab ohutuse seisukohalt olulisi osi ja funktsioone vastavalt kasutusjuhendile."],"g-rueckhalt":["Kuidas käitute olemasoleva juhi turvasüsteemiga?","Tõstukil on kohustuslik turvasüsteem.","Kasutage seda sõidu ajal õigesti.","Kasutage ainult ebatasastel põrandatel.","Lühikeste reiside jaoks lülitage see välja.","Kavandatud turvasüsteeme tuleb kasutada vastavalt tootja juhistele; need pakuvad erilist kaitset kallutusjuhtumite korral."],"g-mangelmelden":["Mis kehtib kahjustatud kahvliga tõstuki kohta?","Kontrollimisel märkate selgelt painutatud piid.","Võimalusel jaotage koormus teisele piile.","Kuni järgmise hoolduseni sõitke ainult kerge koormaga.","Ärge kasutage tõstukit ja teatage veast vastutavale isikule.","Kahjustatud koorma teisaldusseadmed võivad ebaõnnestuda; Ohutusega seotud defektid nõuavad väljalülitamist kuni selgitamiseni."],"g-einweisung":["Lülitute erinevate juhtseadmetega tõstukile. Mida on vaja enne kasutamist?","Toiming erineb teie eelmisest sõidukist.","Seadmega seotud juhised ja kasutusjuhendi järgimine.","Alati piisab lühikesest selgitusest mitteseotud kolleegilt.","Täiendavat teavet pole, kui teil on tõstukilitsents.","Üldine kvalifikatsioon ei asenda vajalikke juhiseid tegelikult kasutatava seadme kohta."],"g-anbaugeraet":["Peaksite kasutama manust. Mida sa kõigepealt kontrollid?","Uus seade muudab koorma pealevõtmise viisi.","Kas lisaseade sobib sõiduki tüübikinnitusega ja lubatud koormusega.","Ainult kas seadet saab visuaalselt kinnitada.","Kas manuse saab paigaldada ilma dokumentatsioonita.","Lisad võivad muuta allesjäänud kandevõimet ja koorma keskpunkti; Kinnitusi ja kandevõimeteavet tuleb kontrollida."],"g-diagramm":["Miks on vaja kandevõime diagrammi?","Raske koorem on raskuskesega kaugel väljapoole.","Lühima marsruudi määramiseks.","Maksimaalse lubatud koormuse hindamiseks sõltuvalt tõstekõrgusest ja koorma keskmest.","Paagi mahu määramiseks.","Lubatud koormused sõltuvad muuhulgas koorma keskpunkti kaugusest ja tõstekõrgusest."],"g-lastschwerpunkt":["Mis tavaliselt juhtub, kui raskuskese liigub edasi?","Kaugele kahvlite ette ulatub pikk koorem.","Lubatud kandevõime võib väheneda.","Kandevõime aina suureneb.","Kaugus ei mõjuta kallutusmomenti.","Suurem kaugus koormuskeskmest suurendab kallutusmomenti ja võib vähendada lubatud kandevõimet."],"g-gabelabstand":["Kuidas peaksid kahvlid sobiva kaubaaluse üles korjama?","Soovite üles võtta ühtlaselt laaditud kaubaaluse.","Piidega võimalikult lähedal ja ainult ühes nurgas.","Nii suure vahemaaga, et kaubaalus kaldub küljele.","Sobiva piide vahega ning piisava alusvankri ja tugipinnaga.","Koormus tuleb toestada kindlalt ja võimalikult ühtlaselt üle kahvliharude."],"g-schieflast":["Koorem on ebastabiilselt virnastatud. Mis on õige?","Pappkastid võivad tõstmisel maha kukkuda.","Alustage aeglaselt; laeng stabiliseerub ise.","Enne koorma pealevõtmist kinnitage see piisavalt või laske uuesti kokku panna.","Tõstke koorem pea kõrgusest kõrgemale, et see ei segaks.","Lahtine või ebastabiilne veos võib kukkuda ja ohustada inimesi; esmalt rakendage ohutusmeetmeid."],"g-personen":["Kas inimest saab tõsta tavaliste kahvlite peal?","Kolleeg tahab jõuda valguseni.","Jah, kui kolleeg kannab kiivrit.","Ei, inimesed võivad vastavalt erinõuetele kasutada ainult selleks ettenähtud ja lubatud rajatisi.","Jah, kui läheneda vaid väikesele kõrgusele.","Tavalised kahvlid ei ole isiklik tööplatvorm; Inimeste transportimisel ja tõstmisel kehtivad erinõuded."],"g-transporthoehe":["Kuidas te tavaliselt kaubaalust transpordite?","Tee on vaba ja tasane.","Kui koorem on tõstetud ainult nii palju kui vaja ja vastavalt kasutusjuhendile.","Kui koorem on tõstetud võimalikult kõrgele, et oleks paremini näha.","Tugevalt ette kallutatud tõstemastiga, olenemata koormast.","Madal transpordiasend vähendab ümbermineku ja kokkupõrke ohtu; Seadme juhised on määravad."],"g-kurvenfahrt":["Miks on tõstukiga kiire kurvide läbimine ohtlik?","Tahad kiiresti kitsast rajast väljuda.","Sest see lihtsalt tühjendab akut kiiremini.","Sest tõstuk juhib automaatselt paremini.","Kuna külgmised jõud mõjutavad stabiilsust ja võivad põhjustada ümberminekut.","Kurvides tulevad mängu lisajõud; kiirus tuleb kohandada koormusele ja tingimustele."],"g-ladebruecke":["Mida kontrollite enne laadimissillale sõitmist?","Peaksite sõitma veoautoga.","Kas tee tundub piisavalt lai.","Kandevõime, kindel tugi ja kaitse käiguvahetuse eest, samuti sõiduki kinnitamine.","Lihtsalt kas valgustus on sisse lülitatud.","Laadimissildad ja -sõidukid peavad olema liikumise vastu kindlustatud ja koormale sobilikud."],"g-fussgaenger":["Kuidas käitute jalakäijatega segasel ristmikul?","Visuaalsed ühendused on piiratud.","Sõitke sobiva kiirusega, vajadusel peatuge ja tagage ohutu nähtavus.","Nõudke koorma kandmisel alati eesõigust.","Lihtsalt müra ja jätka sõitu.","Jalakäijatel on erikaitsevajadused; Kiirus, nähtavus ja side tuleb kohandada liiklustrassiga."],"g-batterieladen":["Millele tasuks draivi aku laadimisel erilist tähelepanu pöörata?","Kasutatakse akulaadimisjaama.","Laadimiskohta saab valida sõltumata tootja juhistest.","Lahtise tule kasutamine on lubatud seni, kuni tõstuk seisab.","Sobiv laadimisala, piisav ventilatsioon ja tootja spetsifikatsioonid ning tule- ja plahvatuskaitse.","Laadimisel võivad ohud tekkida elektrienergiast, gaasidest ja kemikaalidest; ettenähtud kaitsemeetmeid tuleb järgida."],"h-beauftragt":["Millistel tingimustel on teil lubatud iseseisvalt kasutada tõstukiplatvormi?","Ettevõttes tuleks kasutada tööplatvormi.","Kui teil on auto juhiluba.","Kui olete sobiv, juhendatud või kvalifitseeritud ja tööandja poolt tellitud.","Kui olete kunagi näinud tööplatvormi.","Tööandja peab tagama tegevusnõuetele vastava sobivuse, kvalifikatsiooni ja ülesanded."],"h-vorpruefung":["Mida tuleks enne tõstukiga töö alustamist kontrollida?","Lava oli üleöö õues.","Visuaalne ja funktsionaalne test vastavalt tootja juhistele, sealhulgas ohutusseadised.","Just lava värv ja vanus.","Kas töömaterjal on juba platvormil.","Enne kasutamist tuleb masinat, juhtseadiseid, avariifunktsioone ja nähtavaid kahjustusi kontrollida vastavalt kasutusjuhendile."],"h-tragfaehigkeit":["Milline teave määrab töökorvi lubatud koormuse?","Kaks inimest tahaksid kaasa võtta lisatööriistu.","Inimesed võivad vabalt hinnata lubatud kogumassi.","Loeb ainult kõige raskema inimese kaal.","Inimeste, tööriistade ja materjalide kandevõimet ei tohi ületada.","Nimikoormus viitab kogu lubatud koormusele, kaasa arvatud mis tahes veetav materjal."],"h-untergrund":["Millele sa enne tugedega lava püsti panemist mõtled?","Töötate täidetud ala lähedal.","Ainult poomi käeulatuses.","Kontrollige vastavalt juhistele aluspinna kandevõimet ja tasasust ning sobivat tuge.","Väiksemal võimalikul arvul laiendatud tugedel.","Ebapiisav maapind või vale tugi võib põhjustada stabiilsuse kaotuse."],"h-wind":["Puhub tugev tuul. Kuidas sa sellega hakkama saad?","Leiad end välilavaga.","Järgige tootja poolt kehtestatud piirnorme ja nende ületamisel peatage töö või laske korv ohutult alla.","Laiendage platvormi nii kaugele kui võimalik, et see oleks stabiilsem.","Reageerige ainult siis, kui lahtised esemed kukuvad alla.","Tootja poolt lubatud tuuletingimused on tööpiirangud; Tuul võib tekitada ohtlikke lisajõude."],"h-strom":["Peate töötama õhuliini lähedal. Mis on ülioluline?","Tööpiirkonnas on elav liin.","Kiiver asendab ohutu distantsi hoidmist.","Lihtsalt isoleerige korv ja töötage ilma koordineerimata.","Selgitage ohuala ja tagage vajalikud kaitsekaugused või muud sobivad meetmed.","Elektriline välklamp on võimalik ka ilma otsese kontaktita; Enne operatsiooni algust tuleb kindlaks määrata vajalikud kaitsemeetmed."],"h-notablass":["Miks on vaja teada hädalangetamise protseduuri?","Tavalise juhtimise rike on võimalik.","Et rikke korral oleks seadme järgi võimalik ohutu päästmine.","Nii et seade töötaks tavatöös kiiremini.","Regulaarse testimise asendamiseks.","Hädajuhtimisseadmed, hädaolukorra langetamine ja päästekontseptsioonid peavad enne kasutamist olema teada ja toimima."],"h-gelaender":["Kuidas saavutate töökorvis lisakõrgust?","Montaažipunkt on teie käeulatuses.","Ronige korviaeda.","Asetage laud piirdele.","Kasutage sobivat piisava töökõrgusega platvormi; ärge ronige reelingute peale.","Aia otsa või improviseeritud kõrgustesse ronimine seab ohtu kukkumiskaitse."],"h-psaga":["Millised nõuded kehtivad isiklikele kukkumiskaitsevahenditele?","Kasutate tööplatvormi, millele on ette nähtud turvasüsteem.","Igasugune kinnituspunkt väljaspool korvi on alati piisav.","Järgige riskianalüüsi, tootjateavet ja sobivaid kinnituspunkte.","Ärge kasutage kaitset, kui korvil on piirded.","Kas ja millised isikukaitsevahendid on vajalikud, määrab riskianalüüs, etapi ehitus ja kasutusjuhend."],"h-verfahren":["Kas lava saab liigutada tõstetud platvormiga?","Töökoht on mõne meetri kaugusel.","Ainult juhul, kui mudel ja kasutustingimused seda võimaldavad vastavalt tootja juhistele.","Alati, kuni kõik kinni peavad.","Ei, mitte kunagi sõltumata disainist ja tootja kinnitusest.","Ülestõstetud asendis liikumine sõltub seadmest ja on lubatud ainult lubatud töötingimustes."],"h-kollision":["Mida tuleb kraanade või muude masinate läheduses töötamisel korraldada?","Liikuvad osad võivad ulatuda töökorvi.","Mitte midagi; töökorv on alati nähtaval.","Sõitke töökorviga alati üle teiste masinate.","Koordineerige tööpiirkondi, et vältida kokkupõrkeid või pigistuskohti.","Masina samaaegne töö nõuab koordineeritud tööprotsesse ja kaitset kokkupõrgete või kinnikiilumise eest."],"h-einstieg":["Kuidas töökorvi siseneda või sealt lahkuda?","Jõuate korvini maapinnal.","Ronige üle välispiirde.","Läbi ettenähtud juurdepääsu ohutus asendis vastavalt kasutusjuhendile.","Selle kõrvale asetatud redeli kaudu, mille nool on väljatõmmatud.","Tuleb järgida ettenähtud juurdepääsu ja tootja juhiseid; Kontrollimatu üle ronimine kujutab endast kukkumisohtu."],"h-defekt":["Hädaseiskamisseade ei tööta. Mida sa teed?","Defekti avastate ülevaatuse käigus.","Ärge kasutage platvormi ja teatage defektist.","Jätkake töötamist, kui tavalised juhtseadised töötavad.","Kleepige lüliti kinni, et keegi seda ei kasutaks.","Ohutusseadme rike on ohutuse seisukohalt oluline defekt ja takistab ohutut töötamist."],"h-sicht":["Sõiduliikumist pole takistuse tõttu näha. Kuidas te sellesse suhtute?","Peaksite teisaldama liikuva lava.","Sõitke aeglaselt ilma nähtavuseta.","Toetuge lihtsalt kauguse indikaatorile.","Peatage liikumine ja tagage nähtavus või ohutu juhendamine vastavalt kasutusjuhendile.","Enne protseduuri tuleb ohutult üle vaadata inimesed, takistused ja liiklusteed."],"h-rettung":["Mida hõlmab kasutuselevõtu planeerimine suurematel kõrgustel töötades?","Lava kasutatakse kõrvalises piirkonnas.","Ainult planeeritud tööaeg.","Sobiv päästekontseptsioon ligipääsetavate, koolitatud inimeste ja hädaolukorras langetamise protseduuridega.","Eeldus, et tuletõrje lahendab iga probleemi kohe.","Tõhus pääste tuleb eelnevalt organiseerida, isegi kui tavajuhtimisseadmed ebaõnnestuvad."],"k-befaehigung":["Mida on vaja kraana iseseisvaks kasutamiseks?","Uus töötaja peaks kraanatööd üle võtma.","Sobivus ja nõutav kvalifikatsioon, juhendamine ja vastav ülesanne.","Piisab auto juhiloast.","Ühekordsest vaatamisest piisab.","Kraanatöid tohivad teha ainult kvalifitseeritud ja volitatud isikud; Seadmete juhendamine on selle osa."],"k-funktionspruefung":["Mida on vaja kraana kontrollimiseks enne vahetuse algust?","Võtate üle siseruumides kasutatava kraana.","Lihtsalt lugege andmesildilt tööaega.","Kontrollige ohutuse seisukohalt olulisi funktsioone ja nähtavaid defekte vastavalt kasutusjuhendile.","Katsetage kraanat maksimaalse koormusega ilma kontrollimata.","Kohustuslik töökontroll aitab tuvastada ohtlikud defektid varajases staadiumis."],"k-traglast":["Mis tähtsus on lubatud kandevõimel?","Koormat tuleb tõsta.","See on mittesiduv soovitus.","See kehtib ainult siis, kui konks on täielikult sisse tõmmatud.","Vastava tööolukorra lubatud kandevõimet ei tohi ületada.","Teatud tüüpi kraanade lubatud koormused võivad sõltuda raadiusest, noole asendist ja relvastusest."],"k-personen":["Mis kehtib rippuva koormuse all olevate inimeste kohta?","Koormus viiakse üle tööala.","Ohuala tuleb hoida vabana; rippuva koorma alla ei tohi keegi astuda.","Kiiver võimaldab jääda otse selle alla.","Lühikesed ülekäigud on lubatud, kui kraana liigub aeglaselt.","Rippuvad koormad kujutavad endast kukkumis- ja muljumisohtu; Inimesed tuleb ohualast eemale hoida."],"k-signale":["Te ei näe ründajat ja saate vastuolulisi signaale. Mida sa teed?","Suhtlus on ebaselge.","Jätkake viimast draivi käsku.","Peatage liikumine ja tehke suhtlus selgeks.","Pange koorem alla kiiremini, ilma nõu pidamata.","Ohutu koorma liikumine nõuab selgeid signaale ja selget suhtlust."],"k-sicht":["Kes toetab transpordi ajal, kui kraanaoperaator ei näe täielikult koormateed?","Esiku sammas varjab teed.","Inimene, kes juhtub eelneva kokkuleppeta mööda minema.","Mitte keegi; ainult konks on oluline.","Sobiv, juhendatud inimene selgelt kokkulepitud arusaamisega.","Kui koormatee pole nähtav, on vaja vastavat juhendamist või muud ohutut lahendust."],"k-ruck":["Miks tuleks kraana tõmblevaid liigutusi vältida?","Raske koorem hakkab kõikuma.","Need tekitavad täiendavaid dünaamilisi pingeid ja võivad koormust destabiliseerida.","Need vähendavad põhimõtteliselt igasugust pendli liikumist.","Need suurendavad alati nimikandevõimet.","Kiirendus- ja pidurdusjõud suurendavad kraana ja troppide koormust."],"k-sperrbereich":["Mida peaks kontrollima enne koorma õõtsumist ühisalal?","Teised töötajad töötavad läheduses.","Kas koorem sobib visuaalselt kraanaga.","Kas ohuala on turvatud ja inimesi ei ohusta.","Kas koorem saab kanda võimalikult kõrgele kõigist kõrgemale.","Pöörlemis- ja koormateed peavad olema vabad kaitsmata inimestest."],"k-stuetzen":["Mis on tugijalgadega autokraana jaoks ülioluline?","Kraana asetatakse osaliselt täidetud pinnasele.","Just tee laius.","Tugiplaatide värv.","Kandev alus ning tugi ja koormuse jaotus vastavalt paigaldus- ja tootja juhistele.","Paigaldus mõjutab oluliselt stabiilsust, eriti muutuvates pinnasetingimustes."],"k-wetter":["Tuulepuhang paneb koorma oluliselt kõikuma. Mis on õige?","Töötate õues.","Peatage liikumine ohutult ja järgige lubatud töötingimusi.","Kiirendage liikumist kiiresti.","Jätkake koorma tõstmist hoolimata tootja poolt kehtestatud piirnormide ületamisest.","Tuul ja kõikuvad liigutused võivad koorma ja kraana destabiliseerida; Taotluspiirangutest tuleb kinni pidada."],"k-freileitung":["Mis kehtib kraanade kasutamisel õhuliinide läheduses?","Poom või koorem võib joonele läheneda.","Mittejuhtiva koormuse korral on vahekaugused ebaolulised.","Enne töö alustamist selgitage vastutavate isikutega ohuala ja vajalikud kaitsemeetmed.","Toetuge ainult kraanajuhi enda reaktsioonile.","Kontakti ja pinge ülevooluga kaasnevad ohud; ohutud kaitsekaugused või muud meetmed."],"k-sichern":["Mida teete enne kraana juurest lahkumist?","Töö katkeb.","Laske koormal rippuda.","Jätke töötava ajamiga kraana järelevalveta.","Langetage koorem ohutult ja kinnitage kraana vastavalt kasutusjuhendile.","Rippkoormusi ei tohi jätta kontrollimata; Kraana ja koorem tuleb ohutult parkida."],"k-lastanschlag":["Kuidas teada saada, kas kasutatud tropp sobib?","Koormat tuleb tõsta tõsterihma abil.","Märgistuse, kandevõime, seisukorra ja kinnituse tüübile sobivuse poolest.","Just tõsterihma värvi järgi.","Sest seda kasutati juba eile.","Kandevõime ja seisukord peavad olema piisavad, arvestades kinnitustingimusi."],"k-stopp":["Inimene siseneb ootamatult koormusteele. Mida sa teed?","Praegu liigub kraana koormat.","Peatage liikumine viivitamatult ja laske ohuala puhastada.","Andke lihtsalt hoiatussignaal ja jätkake sõitmist.","Tõstke koorem kõrgemale ja sõitke sellest üle.","Inimesi tuleb kaitsta koorma liikumise eest; Vahetu ohu korral tuleb liikumine peatada."],"k-neuerkran":["Saate tundmatu juhtimisseadmega kraana. Mis on õige?","Juhtnupud on varasemast erinevad.","Kui kahtlustate, proovige tavalisi võtmeid.","Laske kellelgi teisel ilma väljaõppeta ette sõita.","Enne iseseisvat kasutamist saate vajalikud seadmega seotud juhised.","Isegi kogenud kraanaoperaatorid vajavad teadmisi konkreetsete kasutatavate juhtimisseadmete, kaitseseadmete ja piirangute kohta."],"a-kennzeichnung":["Kuidas teada tropi lubatud kandevõimet?","Tahad valida tropi.","Materjali lõhn.","Asjakohasel, loetaval kandevõime märgisel ja tootja teabel.","Säilitusaja pikkuse kohta.","Lubatud kandevõime määratakse märgistuse ja töötingimustega."],"a-sichtpruefung":["Märkate tõsterihma selget lõiget. Kuidas te sellesse suhtute?","Bänd peaks kandma koormat.","Ärge kasutage teipi ja saatke seda testimiseks või tagasilükkamiseks.","Katke lõige teibiga.","Kasutage seda ainult eriti kergete koormate jaoks.","Kahjustatud tekstiiltropid võivad ebaõnnestuda ja neid tuleb hinnata kasutuselt kõrvaldamise kriteeriumide kohaselt."],"a-neigungswinkel":["Mis juhtub, kui tropi kiudude kaldenurk on suurem kui vertikaal?","Kahe ahelaga riidepuu laiutab rohkem.","Keermejõud vähenevad alati.","Keermejõud jäävad samaks.","Kiududes olevad jõud suurenevad; Lubatud nurkadest ja kandevõimetest tuleb kinni pidada.","Kui levik suureneb, suureneb tõmbejõud tugikeera kohta."],"a-schwerpunkt":["Miks on vaja teada koorma raskuskeset?","Koormus on üles ehitatud ebaühtlaselt.","Et koorem püsiks tõstmisel stabiilne ega kukuks kontrollimatult ümber.","Troppide värvi valimiseks.","Et koorem saaks kiiremini pöörata.","Ebasoodsad kinnituspunktid või raskuskeskme asend võivad põhjustada kallakuid, libisemist või kaldu."],"a-kantenschutz":["Tõsterihm asetseb vastu komponendi teravat serva. Mida tuleks teha?","Komponent tuleb üles tõsta.","Tõstke koorem kiiresti enne rihma kahjustamist.","Kasutage sobivat servakaitset ja kontrollige kinnituse tüüpi.","Puhastage koormapinda ainult lapiga.","Teravad servad võivad kahjustada tugikiude; troppimisvarustust tuleb vastavalt kaitsta."],"a-haken":["Millele tropi kinnitamisel tähelepanu pöörad?","Sa kasutad lastikonksu.","Asetage tropp konksu otsa küljele.","Hoidke kaitseklapp püsivalt lahti.","Laadige konks ettenähtud viisil konksu põhja ja jälgige ohutusseadmeid.","Lubamatu koormus konksu otsale ja kinnituse puudumine võib viia selle lahtihaakimiseni."],"a-knoten":["Kas liiga pikka tõsterihma saab sõlmega lühendada?","Peatuse pikkus ei sobi.","Ei; Kasutage ainult sobivat, heakskiidetud tüüpi troppi või sobivat troppi.","Jah, kui sõlm on väga tugevalt kinni tõmmatud.","Jah, seni, kuni koorem parasjagu paigal on.","Sõlmed võivad tekstiiltroppe oluliselt nõrgendada ja nende pikkuse improviseeritud reguleerimine ei ole lubatud."],"a-probehub":["Miks tõstetakse koormat alguses ettevaatlikult?","Tahad ohutult transportida.","Et ta saaks võimalikult kiiresti tööle sõita.","Troppide asukoha, stabiilsuse ja raskuskeskme kontrollimiseks.","Kuna kandevõime suureneb automaatselt.","Kontrollitud esimene löök aitab tuvastada valed peatumised ja ebastabiilsed koormaasendid."],"a-lastweg":["Kus on inimestel lubatud koorma transpordi ajal viibida?","Koorma teisaldamine toimub kraanaga.","Otse koorma all kaitsekiivriga.","Koorma peal, kui nad suudavad vastu pidada.","Väljaspool ohuala ja mitte rippuva koorma all.","Isegi hoolika kinnitamise korral on oht, et koorem langeb või kõikub."],"a-haende":["Kuidas vältida muljumisvigastusi võõrutamisel?","Koormus läheneb tugipinnale.","Hoidke käed ja jalad muljumisalast eemal ning kasutage sobivaid abivahendeid.","Hoidke koormat palja käega.","Asendi korrigeerimiseks seiske koorma ja seina vahel.","Koorma ja toe vahele tekivad ohtlikud muljumiskohad."],"a-vierstraenge":["Mis kehtib neljajalgse vedrustuse koormuse jaotuse kohta ilma koormuse kompenseerimiseta?","Kinnitatakse jäik koorem.","Kõik neli ahelat kannavad paratamatult sama palju.","Ilma ühtse jaotuse tõendamiseta ei tohi kandevõimet kasutada nelja võrdselt koormatud ahela üldhinnanguna.","Kaldenurk on siis ebaoluline.","Jäikade koormustega on võimalik kiudude ebavõrdne koormus; Projekteerimisel ja lubatud kandevõimel tuleb seda arvesse võtta."],"a-chemikalien":["Mis kehtib kemikaalidega kokkupuutel tekstiiltroppide kasutamisel?","Töötate tundmatu vedelikuga.","Bändi värv näitab usaldusväärselt selle vastupidavust.","Iga tekstiilriba on vastupidav kõikidele kemikaalidele.","Kontrollige vastupidavust ja tootjateavet; Ärge kasutage sobimatuid vahendeid.","Kemikaalid võivad troppe rünnata ja märkamatult vähendada nende kandevõimet."],"a-aufbewahrung":["Kuidas troppe pärast kasutamist hoitakse?","Missioon on läbi.","Puhastage, kuivatage ja kaitske kahjustuste eest vastavalt tootja spetsifikatsioonidele.","Maapinnale kinni jäänud kaitsmata koormuse all.","Igal teraval väliskonksul.","Nõuetekohane ladustamine hoiab ära enneaegse kulumise ja muudab visuaalse kontrolli lihtsamaks."],"a-auswahl":["Mida tuleks tundlike või teravate servadega koormate puhul eriti arvestada?","Värvitud masinaosa tuleb teisaldada.","Ainult transpordi kiirus.","Sobivad tropid ja kaitsemeetmed koormapinnale ja servadele.","Olenemata koormusest, alati sama terastross.","Kinnituse tüüp ja materjal peavad vastama geomeetriale, pinnale ja ohule."],"a-abstimmung":["Kraanaoperaatoril pole teist vaadet. Kuidas sa juhiseid annad?","Olete määratud ründajaks.","Lehvitad oma suva järgi, kuni algab liikumine.","Sa lihtsalt helistad ja lähed minema.","Selgelt kokkulepitud siltide või muu usaldusväärse side kaudu.","Ründajad ja kraanaoperaatorid peavad suhtlema selgelt; Kui see on ebaselge, tuleb liikumine peatada."],"b-qualifikation":["Mida vajab inimene hüdraulilise ekskavaatori ohutuks kasutamiseks töötamise ajal?","Ehitustööde peaks üle võtma uus inimene.","Vastav kvalifikatsioon, seadmega seotud juhendamine ja nõutav ülesanne.","Ainult auto juhiluba.","Lihtsalt kiire vaatlus operatsioonist.","Tööandja peab tagama vajaliku kvalifikatsiooni ja juhendama operaatorit ülesande täitmiseks asjakohaselt."],"b-pruefung":["Mida sisaldab igapäevane masinaülevaatus?","Võtate üle ekskavaatori.","Kontrollige värvi värvi ja istmepolsterdust.","Visuaalne kontroll ja funktsionaalsed testid vastavalt kasutusjuhendile, näiteks lekete ja kahjustuste tuvastamiseks.","Liigutage poomi täiskiirusel, kuni see peatub.","Hüdraulika, šassii ja turvaseadmete kahjustused võivad põhjustada tõsiseid õnnetusi."],"b-leitungen":["Mida peab teadma maa-aluste torude kohta enne kaevandamist?","Peaksite kraavi kaevama.","Ainult planeeritud kaeveaugu ligikaudne sügavus.","Maapealse märgistuse värv on piisav.","Täpsustage võimalike liinide asukoht ja määrake sobivad turva- ja uurimismeetmed.","Elektri-, gaasi- või veetorustikul võivad kahjustada saada eluohtlikud tagajärjed."],"b-schwenkbereich":["Kuidas kaitsta inimesi ekskavaatori kiigealal?","Sa korjad poomiga materjali.","Piirake või kindlustage ohuala ja hoidke inimesed eemal.","Enne pööramist liigutage labidat aeglaselt.","Sõitke ala üle peade.","Pöörlev pealisehitus ja seadmed tekitavad muljumis- ja kokkupõrkeohtu."],"b-boeschung":["Mis on oluline kaeveaugu serva lähedal töötades?","Ekskavaator seisab rajatud või täidetud pinnasel.","Ainuüksi kaevamissügavus määrab lubatud paigutuse.","Pöörake tähelepanu nii kandevõimele ja serva kinnitusele kui ka nõutavatele vahemaadele vastavalt riskihinnangule.","Sõitke sõiduulatuse säästmiseks võimalikult äärele.","Ebapiisava kliirensi või stabiilse pinnase korral võib muldkeha ebaõnnestuda ja masin kukkuda."],"b-standsicherheit":["Miks on kalle ja pinnas kasutamiseks üliolulised?","Ehitusplats on kallakul.","Masin on võrdselt stabiilne igal pinnal.","Roomikalused veermikud välistavad igasuguse ümbermineku ohu.","Ebatasasused ja kalded võivad stabiilsust mõjutada; Järgige kasutuspiiranguid.","Stabiilsus ja ümberminekuohutus sõltuvad põrandast, seadmetest, koormast ja masina asendist."],"b-wechselgeraet":["Mida kontrollite pärast ekskavaatori kopa vahetamist kiirühendusega?","Paigaldati uus lisand.","Kas see on vastavalt kasutusjuhendile õigesti lukustatud ja kinnitatud.","Lihtsalt kas labida värv sobib.","Kas hüdraulika töötab võimalikult vaikselt.","Vigased lukud võivad põhjustada lisaseadmete kukkumist."],"b-heben":["Millele tuleks tähelepanu pöörata vabalt rippuva koorma tõstmisel ekskavaatoriga?","Ekskavaatorit kasutatakse tõstetöödeks.","Määrav on ainult tavaline kaevamisjõud.","Järgige lubatud tõstekoormust, sobivaid kinnituskohti ja ettenähtud kaitseseadmeid.","Koorma saab haakida kopa hammaste külge.","Tõstmine on lubatud ainult ettenähtud töötingimustes sobivate seadmetega."],"b-rueckwaerts":["Pead tagurdama, aga teed ei näe. Mis on õige?","Teised töötajad on lähedal.","Sõitke ettevaatlikult, ilma nähtavuseta.","Lihtsalt müra ja jätka sõitu.","Peatuge, tagage nähtavus ja ohuala või korraldage sobivad juhised.","Tagurdamine ei tohi inimesi ohustada; piiratud nähtavus nõuab lisameetmeid."],"b-kabel":["Poom võib jõuda õhuliini lähedale. Mida sa teed?","Töötate kitsal ehitusplatsil.","Täpsustage ohuala ja sobivad kaitsemeetmed eelnevalt vastutavate isikutega.","Ignoreeri joont, kui poom on värvitud.","Liigutage poomi ainult eriti kiiresti.","Elektrilised ohud tulenevad kokkupuutest ja sähvatusest; ohutud vahemaad ja kaitsemeetmed on vajalikud."],"b-verlassen":["Kuidas ekskavaatorit enne lahkumist parkida?","Teete pausi.","Jätke poom vabalt vedelema.","Asetage töövahendid ohutult maha ja kindlustage masin liikumise ja lubamatu kasutamise eest.","Jätke mootor tööle ja kabiin lahti.","Madaldatud töövahendid ja kaitse tahtmatu liikumise eest vähendavad õnnetuste ohtu."],"b-hydraulik":["Märkate kahjustatud torustikul kõrge rõhu all olevat hüdroõli. Mis on õige?","Liin lekib.","Tundke leket käega.","Kinnitage uus surve all olev klamber.","Lülitage masin ohutult välja, laske rõhku alandada ja laske remonti teha volitatud spetsialistidel.","Kõrge rõhu all olev hüdraulikavedelik võib põhjustada tõsiseid vigastusi; ärge kunagi kontrollige lekkeid käsitsi."],"b-unterbau":["Mis on ebastabiilsel pinnal sõitmise oht?","Maa on pärast vihma pehme.","Masin võib vajuda, libiseda või ümber minna.","Ajam muutub automaatselt laiemaks.","See muudab pöördevahemiku turvalisemaks.","Ebapiisav kandevõime võib oluliselt halvendada stabiilsust ja sõiduohutust."],"b-arbeitsgeraet":["Kas keegi saab töötada ülestõstetud seadme all?","Inimene tahab midagi labida all kontrollida.","Jah, kui mootor töötab tühikäigul.","Ei, mitte ilma vajaliku ohutu toestuse ja töövahendite kinnitamiseta.","Jah, kui isik kannab kaitsekiivrit.","Hüdraulikaseadmed võivad uppuda; Hooldustöödeks on vaja turvalisi töövahendeid."],"b-geraeteart":["Vahetate hüdroekskavaatorilt rataslaadurile. Mida nõutakse?","Toimimine ja liikumiskäitumine on erinevad.","Just samad jalanõud.","Proovisõit ilma juhisteta.","Uue masinatüübi jaoks vajalik kvalifikatsioon või juhend.","Kvalifikatsioon peab vastama kasutatava masina tüübile ja konkreetsetele töönõuetele."],"g-neigung":["Sõidate koormatud tõstukiga tõusul. Mis on oluline?","Marsruudil on selge kalle.","Juhtige koorem alati allamäge, isegi kui see on raske.","Juhtige koorem ülesmäge ja järgige kallakutel sõitmise juhiseid.","Sõltumata sõidusuunast tõstke kahvel maksimaalselt üles.","Tõusutel ja laskumistel tuleb koorem alati ülesmäge kanda; Järgida tuleb sõidukit ja kasutusjuhendit."],"g-gabelabsenken":["Miks tuleb parkimisel kahvel alla lasta?","Tõstuk on vaheajaks pargitud.","Et teised saaksid kahvlit üles ronida.","Et kahvel jääks eemalt paremini nähtavaks.","Et koorma tõstmine ei tekitaks asjatut komistamise või vigastuste ohtu.","Madalamad koorma käsitsemisseadmed vähendavad väljaulatuvate või kinnitamata kahvlite tõttu õnnetuste ohtu."],"g-fahrerwechsel":["Kolleeg soovib tõstukit laenata. Mis peab olema kohal?","Kolleegil on sinult vaid suuline luba.","Tal peab olema vajalik kvalifikatsioon ja ettevõtte mandaat.","Teie enda ülesanne kehtib automaatselt ka tema kohta.","Isikliku auto juhiloast piisab iga ettevõtte jaoks.","Sõltumatu juhtimine on seotud isikliku sobivuse, väljaõppe, kvalifikatsiooni ja tegevusülesandega."],"g-ladungssicherung":["Kaubaalus sisaldab lahtisi virnastatud kaste. Mis on õige?","Pappkast võib sõidu ajal maha kukkuda.","Kinnitage koorem enne transportimist libisemise ja kukkumise vastu.","Eriti ebatasasel pinnasel sõitke ainult aeglaselt.","Kompenseerige lahtised kastid kõrgema kahvli asendiga.","Koorem peab enne tõstukiga transportimist olema stabiilne ja kukkumise vastu kindlustatud."],"g-bodenbelastung":["Teie ees on piiratud kandevõimega tekk. Kuidas otsustate?","Marsruut viib üle keskmise taseme.","Lihtsalt pöörake tähelepanu veoki kaalule ilma koormata.","Täpsustage tõstukite ja koormate lubatud põrandakoormus.","Sõida hooga, et lagi oleks lühemat aega koormuse all.","Oluline on kogu tegelik pinge alale, sealhulgas sõiduk, koormus ja dünaamilised mõjud."],"g-verkehrswege":["Teie teed ristub tähistatud jalgtee. Mis on õige?","Jalakäijad pääsevad ülekäigurajale igal ajal.","Sarviga saab alati endale eelisjärjekorra nõuda.","Märgistusest võib ilma jälgimiseta üle sõita.","Reguleerige kiirust, pöörake tähelepanu jalakäijatele ja jätkake sõitu alles siis, kui tee on vaba.","Liiklusteedel tuleb sõita inimestega arvestavalt; Hoiatussildid ei asenda ohutut nähtavust ja selget marsruuti."],"g-parkbremse":["Parkite tõstuki tasasele pinnale. Mida see sisaldab?","Soovite mõneks minutiks juhiistmelt lahkuda.","Parkige, rakendage seisupidur ja kindlustage volitamata kasutamise eest.","Jätke sõiduk ainult neutraalasendisse.","Jätke kahvel pea kõrgusele, et keegi seda ei puudutaks.","Enne lahkumist tuleb tõstuk ohutult peatada ja kindlustada tahtmatu liikumise vastu."],"g-typenschild":["Milline teave on tõstuki koormuse puhul siduv?","Tahad raske masina peale võtta.","Hinnanguline kandevõime sõiduki suuruse alusel.","Tootja andmed koormus- või kandevõime diagrammil.","Viimase transporditud kaubaaluse kaal.","Lubatud koormus määratakse tootja info järgi ja sõltub muuhulgas koormuse keskmest ja tõstekõrgusest."],"g-tore":["Lähenete tõstukiga madalale vahekäigule. Mida sa kontrollid?","Sõidukil on kõrguv koorem.","Kas läbipääs koos koorma ja kinnitusega on ohutult võimalik.","Ainult kahvlikanduri kõrgus ilma koormata.","Kas saab kiiremini läbi sõita enne kui värav sulgub.","Enne läbikäike tuleb arvestada vaba kõrguse ja laiusega ning koorma ja sõiduki mõõtmetega."],"g-reifen":["Igapäevase kontrolli käigus leiate tugevalt kahjustatud rehvi. Mida sa teed?","Rehvil on näha ohutuse seisukohalt olulisi kahjustusi.","Sõidate aeglaselt kuni tavapärase hooldusajani.","Tõstate rehvirõhku ja jätkate sõitu.","Te ei võta sõidukit kasutusele ega teata kahjust.","Kahjustatud rehvid võivad halvendada stabiilsust ja juhitavust; viga tuleb enne kasutamist selgitada."],"h-absperren":["Töötajad kõnnivad teie tööplatvormi alt mööda. Mis on vajalik?","Tööriistade kukkumise oht on olemas.","Sobiv kaitse- või piiratud ala töökoha all.","Lihtsalt teade, kui esimest korda mööda lähete.","Hoidke tööriistu korvi servast võimalikult kaugel.","Kõrgendatud töökohtade all olev tööala peab olema kaitstud kukkuvate osade põhjustatud ohu eest."],"h-werkzeuge":["Kuidas transpordite tööriistu töökorvis?","Kõrgusel on vaja mitut väikest tööriista.","Asetage need lõdvalt piirdele, nii et need oleksid hõlpsasti kättesaadavad.","Hoidke ja kinnitage nii, et need ei kukuks maha ega takistaks nende tööd.","Kinnitage taskus oleva piirde välisküljele.","Lahtised esemed võivad kukkuda ja inimesi ohustada; turvaline ladustamine on vajalik."],"h-abstuetzung":["Kaevukaanel seisab tugi. Mida on vaja kontrollida?","Tahad platvormi tõsta.","Lihtsalt veenduge, et kaas oleks kuiv.","Kas koormust saab sel hetkel ohutult vastu võtta.","Kas teisi tugesid pole vaja kasutada.","Aluspinnas ja kokkupuutealad peavad suutma ohutult vastu võtta tugijõude; Kaaneid tuleb hinnata eraldi."],"h-notaus":["Millal tuleks hädaseiskamisseadet kasutada?","Kohe tekib ohtlik liikumine.","Ainult tavalise vahetuse lõpus.","Peatumiseks ägeda ohu korral vastavalt kasutusjuhendile.","Planeeritud langetamise asendusena.","Hädaseiskamist kasutatakse ohu ärahoidmiseks, mitte tavapäraseks juhtimiseks või väljalülitamiseks."],"h-schraegstellung":["Lava kalde hoiatus reageerib. Kuidas te reageerite?","Masin on kaldpinnal.","Madalatel töökõrgustel eirate hoiatust.","Hoiatusest hoolimata sõidate kõrgeimasse tõsteasendisse.","Peatute ja viite lava ohutusse seisukorda vastavalt tootja juhistele.","Kaldehoiatused võivad viidata ebapiisavale stabiilsusele; edasised liigutused ei tohi ohtu suurendada."],"h-umgebung":["Mida tuleb liiklusala lähedusse seadmisel korraldada?","Sõidukid võivad lava puudutada.","Kaitse kokkupõrgete eest ja asjakohane liiklusjuhend.","Pöörake töökorv võimalikult kaugele üle tee.","Lihtsalt hoiatuskõne enne käivitamist.","Tööplatvormid peavad olema kaitstud liiklejatega kokkupõrke eest; paigaldus peab olema vastavalt kinnitatud."],"h-ueberlast":["Käivitub korvi ülekoormuse hoiatus. Mida sa teed?","Kutsuti lisatööriistu.","Lõpetage töö suuremal kiirusel.","Määrake lubatud korvikoormus ja järgige tootja juhiseid.","Lülitage hoiatussignaal püsivalt välja.","Korvi maksimaalset lubatud koormust, sealhulgas inimesi ja materjale, ei tohi ületada."],"h-quetschen":["Ajad korvi katuse alla kinni. Milline oht on eriti oluline?","Korvi kohal on vähe ruumi.","Korvi ja konstruktsiooni vahele kinnitamine või muljumine.","Et mootor kulutab rohkem kütust.","Et sõidusuund muutuks alati automaatselt ümber.","Kitsad ruumid töökorvi kohal või kõrval võivad põhjustada tõsiseid muljumisvigastusi."],"h-stromausfall":["Lava püsib suurel kõrgusel ilma peaajamita. Mis on õige?","Tavaline korvi juhtseade enam ei reageeri.","Ronite ilma ohutuseta poomi alla.","Ootate oma vahetuse lõpuni ilma, et teid teavitataks.","Alustage ettevalmistatud päästetööd koolitatud inimeste ja hädalangetamise abil.","Häirete korral tuleb planeerida ohutu päästmine; Koolitatud inimesed peavad teadma hädaolukorra funktsioone."],"h-transportstellung":["How do you set the stage for a transport?","Tööplatvorm laaditakse sobivale sõidukile.","Viige nool ja platvorm vastavalt kasutusjuhendile transpordiasendisse.","Tie down the platform as far out as possible.","Jätke toed välja, et see võtaks rohkem ruumi.","Ettenähtud transpordiasend ja koorma kinnitus põhinevad tootjal ja transpordispetsifikatsioonidel."],"k-bremsprobe":["Mida näitab kraanapiduri funktsionaalne test enne kasutamist?","You want to be able to hold a load securely.","Kas pidur peatub ja hoiab liikumist ette nähtud viisil.","Just whether the cabin lighting works.","Whether the hook can automatically hold a load.","Enne kasutamist tuleb ohutuse seisukohalt olulisi funktsioone kontrollida vastavalt spetsifikatsioonidele."],"k-schraegzug":["Kas saate kraanaga külgsuunas koormat viltu tõmmata?","The hook is not vertically above the load.","Yes, if the crane still has load reserve.","Ei, koormaid ei tohi tõmmata lubamatute diagonaaltõmmetega.","Yes, if the slings are particularly short.","Diagonaalne tõmbamine võib põhjustada kontrollimatuid liigutusi ning kraanale ja troppidele täiendavat koormust."],"k-verhakt":["A load hangs on the substructure. Mis on õige?","Resistance is felt when lifting.","You keep lifting until it comes away.","You move the load sideways jerkily.","Te peatute ja lasete kinnituse või ummistuse ohutult eemaldada.","Kinnijäänud koormat ei tohi jõuga lahti rebida, kuna võivad tekkida lubamatud jõud."],"k-anzuheben":["Mida kontrollite rippkoorma esmakordsel lühiajalisel tõstmisel?","Koorem tõuseb maapinnast paar sentimeetrit.","Kas see ripub tasakaalus ja peatus on kindel.","Kas inimene suudab end otse koormuse alla panna.","Kas kraana muutub kiiresti pöörates stabiilsemaks.","Lühiajalist juhitavat tõstmist kasutatakse kinnituse, tasakaalu ja koorma ohutu käitumise kontrollimiseks."],"k-lastweg":["Kus peaks olema kraanakoorma transporditee?","Võimaliku koormustee all on mitu töökohta.","Võimalusel hõivatud töökohtade kohal.","Planeeritud selgel teel, kus pole ohtu inimesi.","Alati diagonaalselt läbi kõige aktiivsema piirkonna.","Koormateed tuleb korraldada nii, et rippuvad koormad ei ohustaks inimesi."],"k-signalverlust":["Raadioühendus marssaliga katkeb. Mida sa teed?","Laadimisteed ennast ei näe.","Jätkate liikumist aeglaselt.","Kiigud eksperimentaalselt eelmises suunas.","Peatate liikumise, kuni tekib selge ja kindel arusaam.","Kui side puudub, ei pruugi segane koorma liikumine jätkuda."],"k-haken":["Turvakonks ei sulgu usaldusväärselt. Mis on õige?","Ülevaatuse käigus märgatakse defektset sulgurit.","Enne edasist kasutamist tuleb viga professionaalselt parandada.","Seod klambri kaablisidemega tugevasti kinni.","Konksu kasutate ainult kergete koormate jaoks.","Defektsed kinnitusseadised koormakonksudel võivad põhjustada troppide lahtihaakumist ja need tuleb parandada."],"k-zugrichtung":["Mis on oluline koormuse vertikaaltoestamisel?","Koormus tuleb masinalt tõsta.","Kraana konks peaks olema joondatud koorma raskuskeskmest kõrgemale.","Konks tuleks asetada võimalikult külgsuunas.","Koormat tuleb enne tõstmist lükata.","Koormuse keskpunkti kohal võimalikult vertikaalne jõuefekt väldib lubamatuid külgjõude ja kontrollimatut väljapoole nihkumist."],"k-wartung":["Kraanal on märgata ebatavalist lihvimismüra. Kuidas te sellesse suhtute?","Müra tekib tõstmisel.","Varjake müra suurema kiirusega.","Peatage toimingud ohutult, teatage defektidest ja laske need kõrvaldada.","Jätkake töötamist ette teatamata kuni vaheajani.","Märgatavad muudatused võivad viidata ohutuse seisukohalt olulistele kahjustustele ja nõuavad ülevaatust."],"k-absetzen":["Mida peab tagama kraanakoorma langetamisel?","A heavy load is positioned on a surface.","Koorem võib kaldpinnal olla kinnitamata.","Slings are removed while it is still floating.","Koorem on stabiilne ja kindlustatud ümbermineku või veeremise vastu.","Koorma tohib troppide küljest lahti võtta alles pärast seda, kui see on ohutult maha pandud ja stabiilsus saavutatud."],"l-schwerpunkt":["Miks peab enne löömist teadma raskuskeset?","Transporditakse asümmeetrilise kujuga masinat.","Et koorem püsiks tõstmisel võimalikult tasakaalus.","Et tropid saaks valida nii pikad kui soovitakse.","Et lubatud kandevõime ei mängiks rolli.","Raskuskeskme asend mõjutab koormuse jaotust ja ohutut tasakaalu tõstmisel."],"l-etikett":["Tõsterihmal ei ole loetavat kandevõime silti. Mis on õige?","The marking has become unrecognizable.","Estimate the load capacity based on the color.","Ärge kasutage tõsterihma enne, kui selle sobivus on selgelt tõestatud.","Only use the belt once for small loads.","Suitable markings are required for slings; Seletamatu kandevõime välistab ohutu valiku."],"l-kantenschutz":["A textile band lies over a sharp steel edge. Mis on vajalik?","The load has sharp edges.","Tõmmake lint ilma kaitseta nii tihedalt kui võimalik.","Perform the stroke faster.","Kasutage sobivat servakaitset või muud sobivat kinnitusvahendit.","Sharp edges can damage or cut textile slings; appropriate protection is required."],"l-spreizwinkel":["Kuidas mõjutab suurem kaldenurk troppide koormust?","A load is lifted using two slanting ropes.","Vähem soodsate nurkade korral võivad kiududes olevad jõud suureneda.","Keermejõud kaovad.","The angle has no influence on the stress.","Vähem soodsa peatusnurga korral võivad jõud ahela kohta suureneda; Load capacity tables must be observed."],"l-knoten":["Kas tropiköit saab sõlme kasutades vastavalt soovile lühendada?","Tross on planeeritud koormuse jaoks liiga pikk.","Jah, tihe sõlm parandab kandevõimet.","Ei, kasutage ainult heakskiidetud lühendamis- ja ankurdusmeetodeid.","Jah, kui sõlm on kinnitatud teibiga.","Lubamatud sõlmed nõrgendavad tropid ja muudavad nende lubatud kandevõimet."],"l-zeichen":["Mis kehtib kraanat käitava isikuga suhtlemise kohta?","Koormustee on osaliselt varjatud.","Mitu inimest annavad korraga erinevaid signaale.","Kasutatakse selgeid, eelnevalt kokkulepitud signaale.","Raadiokraanadega pole kunagi sidet vaja.","Selged märgid ja selged kohustused hoiavad ära ohtlikud ebaõiged liigutused."],"l-sichtpruefung":["Millal tuleks troppe nähtavate defektide suhtes kontrollida?","Soovite kasutada troppketti.","Enne kasutamist pöörake tähelepanu väliselt nähtavatele kahjustustele.","Ainult siis, kui õnnetus on juba juhtunud.","Esmakordsel ostmisel ainult üks kord.","Enne iga kasutamist tuleb hinnata ohutut tööseisundit; Nähtavad kahjustused välistavad ohutu kasutamise."],"l-drehung":["A lifted load begins to rotate uncontrollably. Mida sa teed?","The load moves in the load path.","You put your hand between the load and the wall.","Paned end koorma alla ja hoiad sellest kinni.","Hoiad distantsi ja lased liikumisel kontrollitult peatuda.","Koorma kontrollimatud liikumised põhjustavad muljumis- ja löögiohtu; Inimesed peavad ohualast lahkuma."],"l-ablegen":["When can slings be removed from the load?","The load is placed on trestles.","Kui koorem on stabiilne ja ümbermineku või veeremise vastu kindlustatud.","Niipea, kui see esimest korda maad puudutab, olenemata selle asukohast.","While still hovering to save time.","Troppe võib eemaldada alles pärast seda, kui need on ohutult ja stabiilselt maha pandud."],"l-ketten":["Ketttropil on tugevalt painutatud lüli. Mida sa teed?","Kahjustus on nähtav juba enne tõstmist.","Mähi kahjustatud ala traadiga.","Eemaldage kett kasutusest ja laske seda spetsialistidel kontrollida.","Tõstke koormust ainult poole võrra kõrgemale.","Deformeerunud ketilülid on nähtavad kahjustused, mis võivad takistada ohutut kasutamist."],"b-einweiser":["Mis on oluline, kui nähtavus ekskavaatorist on piiratud?","Osa hoonest varjab sõiduala.","Sobivad visuaalsed meetmed või juhised ja selge suhtlus.","Lihtsalt vaadake kapuutsi.","Sõitke läbi pöördeala, hoolimata sellest, et olete nähtamatud.","Kui nähtavus on piiratud, tuleb ohte ennetada täiendavate organisatsiooniliste ja tehniliste meetmetega."],"b-aushub":["Kus saab väljakaevatud materjali hoida ehitussüvendi läheduses?","Kaevu serva ei tohi täiendavalt ohtu seada.","Kuhjake otse servale, et sõiduteed jääksid vabaks.","Hoida piisavalt ohutus kauguses ja vastavalt ehitusplatsi spetsifikatsioonidele.","Asetage ilma täiendava katsetamiseta lahtisele toele.","Väljakaevatud materjal võib lisakoormuste tõttu ohustada mulde ja kaldaid; Ohutuskaugusi tuleb hoida."],"b-personen":["Kas inimesed tohivad ekskavaatori liikumise ajal kiigeplatsile jääda?","Inimene tahab panoraamimise ajal mõõta.","Jah, kui ta kannab kaitsekiivrit.","Jah, kui ekskavaator liigub aeglaselt.","Ei, enne liikumist peab ohuala olema vaba.","Pöördepiirkonnas on tõsiste muljumis- ja löökvigastuste oht; ala tuleb hoida vabana."],"b-ladung":["Kuidas rataslaaduriga materjali ohutult transportida?","Täidetud labidaga tuleks sõita üle õue.","Sobiva madala transpordiasendi ja vaba teega.","Tõstetud labidaga parema nähtavuse tagamiseks.","Avatud uste ja tugeva roolinurgaga.","Sobiv transpordiasend vähendab ümbermineku ohtu ja parandab sõidustabiilsust."],"b-anbaupruefung":["Mida kontrollite pärast lisaseadme ühendamist?","Uus labidas sai külge.","Ainult värvikatte puhtus.","Turvaline lukustamine ja toimimine vastavalt kasutusjuhendile.","Lihtsalt kas seade näeb väljast samasugune välja.","Kiirliitmike valed lukud võivad põhjustada tarvikute tahtmatu vabanemise."],"b-einstieg":["Kuidas pääsete turvaliselt ekskavaatori kabiini?","Trepid on pärast vihma määrdunud.","Ronige poomi kaudu salongi.","Astu röövikutele ühe hüppega.","Kasutage selleks ettenähtud astmeid ja käepidemeid ning puhastage määrdunud astmed.","Sobivad tõusud ja turvalised pidamiskohad vähendavad libisemis- ja kukkumisohtu."],"b-graben":["Kaeviku seinal on praod ja see laguneb. Mis on õige?","Töötate otse kraavi kõrval.","Peatage töö ja laske vastutavatel isikutel kaevekaev kindlustada.","Kraavi sulgemiseks sõitke lihtsalt servale lähemale.","Süvendage kaevet ilma kaitseta veelgi.","Praod ja pinnase liikumised võivad viidata ebastabiilsusele ja nõuda täiendavat ohutuse hindamist."],"b-betanken":["Millele pöörate tähelepanu mullatöömasina tankimisel?","Paak on peaaegu tühi.","Kinnitage mootor ja süüteallikad vastavalt tootja juhistele ning vältige mahavalgumist.","Täitke salongis alati bensiini või diislikütust.","Suitsetage tankimise ajal, kui tuult pole.","Tulekahju ja keskkonnaohud kütuse käitlemisel nõuavad asjakohaseid kaitsemeetmeid."],"b-laufwerk":["Miks on vaja roomikuid ja alusvankrit regulaarselt kontrollida?","Märkate sõidu ajal ebatavalist vibratsiooni.","Et masin saaks kiiremini liikuda.","Kuna kahjustused võivad mõjutada ohutut juhtimist ja stabiilsust.","Kuna tööd on alati lubatud ilma visuaalse kontrollita.","Ajami kahjustused võivad mõjutada manööverdusvõimet, stabiilsust ja ohutut töötamist."],"b-einweisen":["Mida on vaja avaliku jalakäijate liikluse läheduses töötades?","Ekskavaator töötab otse kõnnitee serval.","Jalakäijad peaksid ise kiigeplatsist läbi liikuma.","Lihtsalt kleepige labidale silt.","Piirake ohuala tõhusalt sisse ja suunake liiklust ohutult.","Kolmandad isikud ei tohi siseneda mullatöömasinate ohutsooni; Vajalikud on asjakohased tõkked ja liikluse suunamine."],"g2-fahrweg":["Eesolevale teele on lekkinud vedelikku. Kuidas te sellesse suhtute?","Tõstuk sõidaks otse üle libeda ala.","Lõpetage sõit ja laske ohukoht kinnitada või eemaldada.","Sõitke üles tõstetud kahvliga nii kiiresti kui võimalik.","Loodame kuivematele rehvidele ja jätkame sõitu muutumatul kujul.","Saastunud teed ohustavad stabiilsust ja need tuleb enne nendele sõitmist piisavalt kindlustada."],"g2-sichtladung":["Kõrge kaubaalus blokeerib vaate ette. Mis on õige?","Peate sõitma laoplatsile ja ei näe marsruuti.","Tõstke kaubaalust üles, kuni näete selle alla.","Sõitke ainult sobivaid ja ohutuid meetodeid kasutades, näiteks tagurdades selge vaatega.","Teel saab ikka sõita ka ilma teeviitata või selge vaateta.","Sõidusuund ja nähtavus peavad võimaldama ohutult jälgida liiklusteed; Koormused ei tohi asendada visuaalset kontrolli."],"g2-fussgaengerstop":["Jalakäija peatub kohe tõstuki kõrval. Mida sa teed?","Isik on võimalikus sõidu- ja pöördeulatuses.","Mööduge jalakäijast, kiirendades lühiajaliselt.","Sõitke tõstetud koormaga inimesest mööda.","Peatuge ja jätkake sõitu ainult ohutus kauguses.","Inimesed peavad ohualast eemale jääma; Vajadusel tuleb sõit katkestada."],"g2-hubmast":["Märkate tõstemastil kahjustatud hüdrovoolikut. Mis kehtib?","Hüdraulikaõli lekib seadmest nähtavalt.","Eemaldage tõstuk tööst ja teatage kahjustusest.","Tõstmise ajal kontrollige leket käsitsi.","Tõstke väiksemaid koormaid ainult kuni vahetuse lõpuni.","Hüdraulilised kahjustused võivad põhjustada kontrollimatuid liikumisi; ohutu kasutamine ei ole enne testimist tagatud."],"g2-lagerregal":["Soovite kaubaalust riiulil hoida. Mida sa kõigepealt kontrollid?","Riiulitase on kõrge ja kandevõimet tuleb säilitada.","Lükake kaubaalus riiulile nii kiiresti kui võimalik.","Kontrollige riiuliruumi, koorma kaalu ja vaba hoiuruumi sobivust.","Hinnake kogukaalu ainult kastide arvu põhjal.","Riiulid ja kandevahendid peavad vastama koorma ja ladustamisolukorrale."],"g2-batterieschaden":["Tõstuki aku on väliselt kahjustatud. Mis on õige?","Enne laadimist märgatakse pragusid või ebatavalist vedelikku.","Katke kahjustus kleeplindiga ja laadige kohe.","Laske teisel inimesel akut laadida ilma seda kontrollimata.","Ärge laadige ega kasutage ja teavitage vastutavaid spetsialiste.","Kahjustatud akud kujutavad endast elektri- ja keemilisi ohte ning nõuavad professionaalset hindamist."],"g2-fahrerkabine":["Mis kehtib juhipiirkonna lahtiste esemete kohta?","Tööriistad on põrandal juhtpedaalide kõrval.","Eemaldage esemed ja hoidke tööpiirkond vaba.","Hoidke tööriista sõidu ajal ainult ühe jalaga.","Peida lahtised osad juhiistme alla.","Lahtised esemed võivad blokeerida pedaalid ja kahjustada sõiduki ohutut töötamist."],"g2-uebergabe":["Pärast vahetuse vahetust võtate tõstuki üle. Mida see sisaldab?","Sõidukit kasutas viimati kolleeg.","Oletame, et kolleeg on kõik kontrollid üle võtnud.","Tehke vajalik ülevaatus ja uurige teadaolevate defektide kohta.","Alustage teekonda masinat vaatamata.","Ülevõtja peab enne kasutamist veenduma, et see on ohutus seisukorras."],"g2-transportsicherung":["Kõrge objekt on kaubaalusel lahti. Kuidas sa käitud?","Koormus võib pidurdamisel ettepoole kalduda.","Kandke kahvlit eriti kõrgel, et koorem püsiks stabiilne.","Lihtsalt võtke kurve aeglaselt, minge otse kiiremini.","Seadistage koorem stabiilselt ja kindlustage see ümberkukkumise või kukkumise vastu.","Lahtised koormad tuleb enne transportimist stabiliseerida, et pidurdus- ja sõiduliigutused ei põhjustaks nende kukkumist."],"g2-arbeitsende":["Mis on järelevalveta tõstuki puhul oluline?","Lõpetate oma vahetuse ja lahkute piirkonnast.","Parkige sõiduk turvaliselt ja kindlustage see veeremise ja volitamata kasutamise vastu.","Jätke võti sisse, et kolleegid masina üles leiaksid.","Jätke kahvel silmade kõrgusele, et see oleks nähtav.","Turvaline parkimine hõlmab alla lastud koorma teisaldamist ning kaitset liikumise ja volitamata kasutuselevõtu eest."],"g2-bremsweg":["Miks peate koormuse all pidurdusteekonnale erilist tähelepanu pöörama?","Tõstuk veab raskeid kaupu läbi laokäigu.","Suure koormaga pidurdage alati hiljem kui ilma koormata.","Reguleerige kiirus vastavalt nähtavuse, pinnase ja koormuse tingimustele.","Pidurdamisel tõstke koorem järsult üles, et aeglustada paremini.","Mass ja teeolud mõjutavad peatumisteekonda; kohandatud kiirus on võtmetähtsusega."],"g2-rampe":["Mida kontrollite enne järsust kaldteest ronimist?","Marsruut võib olla sõiduki jaoks liiga järsk.","Sõitke kaldteel maksimaalse kiirusega sõltumata kaldest.","Sõitke tõstetud koormaga üle kaldtee serva.","Lubatud kallet ja ohutut töörežiimi kontrollige sõiduki tehniliste andmete põhjal.","Kasutada tohib ainult ettenähtud kasutuspiirides olevaid kaldteid; Kasutusjuhend ja koormuse juhtimine on määravad."],"g2-zinke":["Kaubaalus on kahvli vahekaugusest laiem. Mida tuleb arvestada?","Plaanite võtta ebatavaliselt suure koormuse.","Reguleerige kahvli kaugus ja kinnituspunktid vastavalt koormale.","Kui koormus on liiga lai, kasutage ainult ühte piiki.","Tõstke koormust nurga all, kuni see jõuab õigesse asendisse.","Ühtlane ja sobiv koormuse neeldumine vähendab libisemist ja ümberminekut."],"g2-betriebsanweisung":["Millist rolli mängib operatiivne liikluskorraldus?","Laos kehtivad tähistatud ühesuuna- ja jalakäijate alad.","Tõstukite puhul kehtivad ainult avalikul teel liiklemise reeglid.","Järgige määratud marsruute ja liiklusreegleid.","Ignoreeri märgistusi, kui sõiduk on laaditud.","Ettevõtte marsruudid ja ohutusreeglid kaitsevad tõstukite liiklust ja jalgsi inimesi."],"g2-nothalt":["Rool reageerib sõidu ajal ebatavaliselt. Mis on õige?","Sõidukit ei saa enam tavapäraselt juhtida.","Sõitke suurematel kiirustel, et muuta rool paremini tundlikuks.","Kompenseerige viga eriti suurte roolipaindetega.","Peatuge turvalises kohas ja laske autot kontrollida.","Kahjustatud juhtimine ohustab ohutut juhtimist; masinat ei tohi jätkata kontrollimatult."],"g2-anschlagkette":["Soovite tõstukiga teisaldada vabalt rippuvat koormat. Mis kehtib?","Koorem peaks kahvlite all konksul rippuma.","Ainult heakskiidetud seadme ja sobiva kandeseadmega.","Iga kett sobib, kui koormus pole raske.","Kinnitage kett otse mõlema kahvli vahele.","Vabalt rippuvad koormad muudavad stabiilsust; Nõutavad on tootja kinnitused ja sobivad rajatised."],"g2-rollenlast":["Silindrikujuline komponent asub kaubaalusel kinnitamata. Mida sa teed?","Koorem võib transpordi ajal veereda.","Lähenege alusele eriti tõmblevalt.","Enne kaubaaluse pealevõtmist kindlustage komponent veeremise vastu.","Asetage piid piisavalt kõrgele, et komponenti ei oleks näha.","Ümmargused või veerevad koormused nõuavad usaldusväärset kaitset asendimuutuste eest."],"g2-pruefplakette":["Kuidas teada saada, kas tõstukit saab kasutada?","Masinale on kleebitud ülevaatuse kleebis.","Iga kleebis asendab alati igapäevast visuaalset kontrolli.","Kliirensi puudumise võib asendada ettevaatliku sõiduga.","Lisaks sõiduki kontrollimisele tuleb arvesse võtta kehtivat testiolekut ja kasutusluba.","Korduvad testimised ja igapäevased töökontrollid täidavad erinevaid ohutusfunktsioone."],"g2-licht":["Laos kustus järsku valgustus. Mis on õige?","Te ei näe enam turvaliselt teel takistusi.","Lõpetage sõit, kuni ohutu nähtavus on tagatud.","Pimedast alast lahkumiseks suurendage sõidukiirust.","Jätkake sõitmist tõstetud kahvlitega ilma visuaalse kontrollita.","Marsruuti, millest ei saa ohutult mööda vaadata, ei tohi sõita ilma tõhusate ohutusmeetmeteta."],"g2-ueberhang":["Koormus ulatub kahvli küljelt palju kaugemale. Mida sa kontrollid?","Soovite kaubaalust transportida läbi kitsa värava.","Kompenseerige külgprojektsioon kiire kõveraga.","Enne sõitmist hinnake kliirensit, stabiilsust ja lubatud kandevõimet.","Sõitke koormaga suurimal kiirusel olenemata selle kujust.","Üleulatused suurendavad kokkupõrkeohtu ning võivad muuta stabiilsust ja vajalikku liiklusruumi."],"g2-wartungsbereich":["Hooldusala ees on tõkked. Kuidas sa käitud?","Teie tavaline marsruut on ajutiselt suletud.","Liigutage korraks tõkkeid ja sõitke märkamatult läbi.","Sõitke koormuse all otse läbi tööpiirkonna.","Jälgige sulgemist ja valige heakskiidetud alternatiivne marsruut.","Piiratud aladele ei tohi loata siseneda ega läbi sõita."],"g2-bremsprobe":["Millal on tööpiduri funktsionaalsuse testimine mõttekas?","Enne tööd valmistate tõstuki ette.","Osana nõutavast kontrollist enne kasutamist.","Tehke seda alles pärast tõsist õnnetust.","Ainult siis, kui veok on juba suure kiiruse saavutanud.","Ohutuse seisukohalt oluliste rajatiste funktsionaalsust kontrollitakse enne kasutamist."],"g2-fahrzeuganhaenger":["Tahad haagist vedada tõstukiga. Mida nõutakse?","Ettevõte planeerib transporti koos juurdelisatud koormaga.","Seo iga haagis kontrollimata hargi külge.","Järgige tootja luba, sobivat sidurit ja lubatud tõmbekoormust.","Lihtsalt suurendage rehvirõhku ja sõitke minema.","Rongisõit on võimalik ohutult ainult tehniliste kirjelduste piires ja sobiva ühendusega."],"g2-rueckfahrt":["Mis on tõstukiga tagurdamisel oluline?","Laokäigus on segane ala.","Vaatamata ümbritsevast olenemata alati ainult tahavaatepeeglisse.","Sõitke ilma nähtavuseta seni, kuni helisignaali on korra vajutatud.","Jälgige ohutult marsruuti ja inimeste piirkonda ning vajadusel laske neid juhendada.","Tagurdamine nõuab selget vaadet või tõhusaid täiendavaid ohutusmeetmeid."],"g2-lastentnahme":["Tõstate kõrgelt riiulilt välja kaubaaluse. Mis on õige?","Palett ei pruugi olla tsentreeritud.","Tõstke koorem turvaliselt üles ja stabiliseerige see enne langetamist.","Laske kaubaalusel selle väljatõmbamise ajal küljele kalduda.","Kontrollige ülestõstetud kaubaaluse altpoolt, et näha, kas see pole kahjustatud.","Kontrollitud tõstmine ja langetamine takistab koormate kukkumist ja ohtlikke liikumisi."],"h2-absenkweg":["Miks peab tööplatvormi alune ala vabaks jääma?","Korv lastakse alla ja selle alla asetatakse materjalid.","Vajutage materjalid korviga alla.","Jälgige ainult operaatori jalaala.","Vältige langetamisel muljumis- ja kokkupõrkeohtu.","Langetusalal ei tohi olla inimesi ega takistusi, mis võivad kinni jääda."],"h2-transporthoehe":["Kuidas liigutada mobiilset lava üle madala käigu?","Kliirens on madalam kui pikendatud poom.","Asetage platvorm vastavalt kasutusjuhendile sobivasse transpordiasendisse.","Jätke poom välja ja liikuge lae alla.","Vajutage korv vastu ukseraami külge.","Liikumisel peavad üldkõrgus ja transpordiasend vastama tootja spetsifikatsioonidele ja läbipääsule."],"h2-bodenoeffnung":["Lava kõrval põrandas on turvamata ava. Kuidas te reageerite?","Ava lähedal asub sõidu- või tugipunkt.","Asetage tugi otse ava servale.","Muutke paigalduskohta või laske professionaalselt kontrollida kandevõimet ja kinnitusi.","Katke ohukoht ainult pappkarbiga.","Avad ja servaalad võivad tugikoormuste mõjul puruneda ja neid tuleb tõhusalt arvesse võtta."],"h2-rettungsperson":["Miks peab teine ​​inimene päästeprotseduuriga kursis olema?","Operaator võib ülaosas töövõimetuks muutuda.","Et töö korvis saaks üldjuhul toimuda ilma turvalisuseta.","Et lava saaks lubatust kiiremini opereerida.","Et hädaolukorras saaks alustada ohutut päästmist.","Päästekontseptsioon peab arvestama maapealse abiga rikke või hädaolukorra korral."],"h2-werkzeugabwurf":["Mis kehtib tööriistade kohta suurel kõrgusel?","Lahtine tööriist võib kukkuda üle korvi serva.","Kinnitage tööriistad nii, et need ei ohustaks kedagi ega kukuks maha.","Koormuse vähendamiseks asetage tööriistad lihtsalt piirdele.","Vajadusel visake tööriistad korvist alla.","Kukkuvad esemed ohustavad allpool olevaid inimesi; Materjali tuleb hoida ohutult."],"h2-trittstufe":["Kast peaks olema korvis täiendava seisuruumina. Mis on õige?","Muidu jõuad vaevalt töökohale.","Asetage kast reelingule ja ronige sellele.","Ärge ronige improviseeritud kõrgustele; Kasutage sobivaid töövahendeid.","Laadige korv tahtlikult üle lubatud kõrguse.","Improviseeritud tõusud kahjustavad kavandatud kukkumiskaitset ja ei ole lubatud."],"h2-lastverteilen":["Millele sa tähelepanu pöörad, kui töökorvis on mitu inimest?","Kaks inimest töötavad korvis raskete tööriistadega.","Hinnake koormust ainult tööriista suuruse põhjal.","Hoidke raskeid tööriistu otse kaitsepiirdel.","Ärge ületage lubatud korvikoormust, sealhulgas inimesi ja tööriistu.","Lubatud kandevõime hõlmab kõiki korvis olevaid inimesi, materjale ja tööriistu."],"h2-abstuetzplatte":["Millal kaalutakse tugede jaoks täiendavaid plaate?","Paigalduspõrand talub ainult piiratud koormust.","Kui see on vajalik koormuse ohutuks jaotamiseks vastavalt spetsifikatsioonidele.","Selleks, et toed oleks võimalikult lähedal ehitussüvendi servale.","Pikema vahemiku kasutamiseks ilma tootja teabeta.","Ohutute tugijõudude jaoks on vaja piisavalt kontaktpindu."],"h2-baugrube":["Lava peaks asuma otse ehituskaevu servas. Mida sa kontrollid?","Aluspinnas võib kaeveaugu tõttu külgmiselt järele anda.","Laiendage toed kaeveõõnde.","Tagada aluspinna piisav ohutuskaugus ja kandevõime.","Kompenseerige risk ainult korvi aeglaselt tõstes.","Kaeveaugud võivad kallaku ja aluspinnase purunemise tõttu stabiilsust mõjutada."],"h2-witterung":["Kasutamise ajal tekib jäätumine. Kuidas sa käitud?","Juhtpinnad ja tööala muutuvad siledaks.","Tõstke lava üles, et vältida lund ja jääd.","Ignoreeri hoiatusi seni, kuni platvorm on valgustatud.","Katkestage töö ja hinnake töötingimused uuesti vastavalt kasutusjuhendile.","Ilmastikumuutused võivad muuta vastutust, toimivust ja ohutuid kasutuspiiranguid."],"h2-aufbaukontakt":["Teraskonstruktsioon piirab korvi teed. Mis on oluline?","Tõstmisel tekib korvi ja kanduri vahele muljumisoht.","Planeerige liigutused nii, et teie keha ja korv ei jääks lõksu.","Tee teekond kiiremaks, et korv kiiremini mööda läheks.","Lükake konstruktsioon koos korviga küljele.","Platvormi ja keskkonna vahelised muljumiskohad nõuavad hoolikat jälgimist ja kontrollitud liikumist."],"h2-sicherheitsabstand":["Millal tuleb lava ohuala piirata?","Objekti alt läbib ühistranspordi marsruut.","Ainult siis, kui objekt on juba alla kukkunud.","Kui liikumine või kukkuvad esemed võivad ohustada kolmandaid isikuid.","Mitte kunagi, sest töökorv hoiab põhimõtteliselt kõik ohud ära.","Lavaalune ja -äärne ala tuleb kaitsta ettenähtavate ohtude eest."],"h2-korbtor":["Mis kehtib töökorvi välisukse kohta?","Olete juba töökõrguses.","Jätke uks lahti, et saaksite kiiremini välja tulla.","Seo uks nööriga püsivalt lahti.","Hoidke uks suletud lukustusmehhanismi järgi.","Kaasasolevad lukud on osa kaitsemeetmetest tööpuurist kukkumise vastu."],"h2-energieleitung":["Mis kehtib juhul, kui õhuliin ei ole ohutult välja lülitatud?","Töötate nende läheduses asuva tõstukiplatvormiga.","Tagage kindlaksmääratud ohutuskaugused ja vajalikud kaitsemeetmed.","Liigutage korvi otse nööri ette, kuni seda ei puudutata.","Usaldage plastrehve ja töötage ilma lünkadeta.","Elektrilised välgud on võimalikud ka ilma otsese kontaktita; Ohutuskaugused on nõutavad."],"h2-schwanken":["Töökorv hakkab ebatavaliselt tugevalt kõikuma. Mis on õige?","Liikumist enam ei kontrollita.","Reguleerige kontrollimatult kiirete vastuliigutustega.","Peatage liikumine ja kontrollige põhjust või töötingimusi.","Lisage ostukorvi rohkem inimesi, et see oleks raskem.","Ebatavaline vibratsioon võib viidata sobimatutele töötingimustele või talitlushäirele."],"h2-ladegeraet":["Elektriliselt juhitava etapi laadimiskaabel on kahjustatud. Mida sa teed?","Ühendamisel on näha kahjustatud isolatsioon.","Puudutage kahjustusi märgade kinnastega.","Vajutage pistik pistikupessa nii kõvasti kui võimalik.","Ärge alustage laadimisprotsessi ja laske kaabel professionaalselt kontrollida.","Kahjustatud elektrijuhtmestik kujutab endast elektrilöögi ja tulekahju ohtu."],"h2-gelaenderanbau":["Kas saate ise piirde eemaldada, et lähemale jõuda?","Komponent takistab inimestel töökohale lähenemast.","Ärge muutke ega eemaldage kaitseseadmeid ise.","Pärast tõstmist keerake reelingud lahti ja paigaldage see hiljem.","Jätkake töötamist ilma piirdeta seni, kuni keegi seisab selle kõrval.","Konstruktsioonikaitseseadmeid ei tohi muuta ilma lubatud spetsifikatsioonide ja ohutute asendusmeetmeteta."],"h2-lastkran":["Kas platvormi saab kasutada kraana koorma tõstmiseks?","Materjali tuleks transportida vabalt rippudes töökorvi kõrval.","Kui kaal on väiksem kui teie enda kehakaal.","Ainult siis, kui tootja ja seadmed seda erikasutust selgesõnaliselt lubavad.","Lihtsalt kinnita konks piirde külge ja tõsta materjal üles.","Tõstukiplatvormid ei ole automaatselt ette nähtud kraanatöödeks ega täiendavate rippuvate koormate jaoks."],"h2-arbeitsvorbereitung":["Millega kaasneb uue asukoha ettevalmistamine?","Sa ei tea veel ehitusplatsi.","Lihtsalt hinnake kaugust lähima parklani.","Olenemata ümbrusest pikendage see kohe täielikult.","Hinnake ohte, pinnast, liiklusteid, päästetööde ja varustuse sobivust.","Asukohaga seotud riskianalüüs on ohutute töötingimuste eeltingimus."],"h2-kabelschlaufe":["Toitekaabel asub üle lava tee. Mis on õige?","Kaabel võib liikumise ajal lõksu jääda.","Puhastage tee ja kaitske elektrikaableid kahjustuste eest.","Kasutage tee künnisena ratastega kaablit.","Tõstke korv ilma põrandapinda kontrollimata.","Üle sõitnud või muljutud kaablid võivad põhjustada elektrilisi ja mehaanilisi ohte."],"h2-leitungsnaehe":["Kes selgitab elektrisüsteemi kaitsemeetmeid?","Platvorm peaks töötama pingestatud seadmete läheduses.","Korvis olev inimene otsustab ainult silma järgi.","Kaasake vastutavad asutused ja rakendage kooskõlastatud kaitsemeetmeid.","Distants määratakse alles pärast töö algust.","Elektrisüsteemide läheduses töötamine nõuab planeeritud ja kooskõlastatud kaitsemeetmeid."],"h2-funkkommunikation":["Miks peavad signaalid põranda ja korvi vahel olema selged?","Maal viibiv inimene abistab manööverdamisel.","Et mitu inimest saaks korraga anda vastuolulisi juhiseid.","Et hädalangetamist saaks ilma juhisteta proovida.","Nii et liigutused tehakse alles pärast selget suhtlust.","Selge suhtlus vähendab ebaõigeid liigutusi ja kokkupõrkeid manööverdamisel."],"h2-neuebedienung":["Lülitute teist tüüpi lavale. Mida nõutakse?","Tööfunktsioonid erinevad oluliselt.","Seadmespetsiifiline juhend enne iseseisvat kasutamist.","Lihtsalt lugesin seadmel oleva ettevõtte logo.","Proovisõit juba pikendatud korviga ilma juhisteta.","Kvalifikatsioon üksi ei asenda konkreetse seadmetüübi juhendamist."],"h2-steckanschluss":["Mida peaksite enne laadija ühendamist kontrollima?","Elektrilist tööplatvormi tuleb laadida.","Kasutage mis tahes pistikupesa olenemata seisukorrast ja kaitsmest.","Kontrollige sobivat ühendust ja kahjustamata kaablit vastavalt tootja juhistele.","Laadimise ajal ühendage toitejuhe regulaarselt lahti.","Sobivad ja terved elektriühendused kaitsevad elektrilöögi ja tulekahju eest."],"h2-absperrpersonal":["Tõstmistööde ajal siseneb inimene piiratud alale. Mida sa teed?","Inimest näete otse töökorvi all.","Jätkake sõitmist, kui isik kannab kaitsekiivrit.","Laske hoiatussignaaliks tööriist nende suunas.","Lõpetage ohtlik liikumine ja laske ala puhastada.","Tõkkepuu ei asenda ohuala jälgimist töö ajal."],"k2-arbeitsplanung":["Mida tuleks lisada töö ettevalmistamisse enne kraanaoperatsiooni?","Koormus, asukoht ja transpordi marsruut on veel kooskõlastamata.","Tõstke esmalt kõige raskem koorem ilma pikema planeerimiseta.","Märkige saali põrandale ainult lühim tee.","Tehke eelnevalt selgeks kandevõime, tropid, koormatee ja ohuala.","Planeeritud kraana liikumine eeldab sobivat koorma käsitsemist, ohutuid marsruute ja kooskõlastatud kaitsemeetmeid."],"k2-hakenposition":["Kuidas on kraana konks enne tõstmist koorma kohal?","Kinnituspunktid on kraana all.","Võimalikult vertikaalselt raskuskeskme kohal vastavalt peatusele.","Nihutage kaugele küljele, nii et koorem liiguks kiiremini sisse.","Igal juhul koorma välisservas, olenemata raskuskeskmest.","Vertikaalne jõu rakendamine ja sobivad kinnituspunktid vähendavad külgsuunalist liikumist ja kontrollimatuid liikumisi."],"k2-hakengabel":["Koormuskonks näitab märgatavat deformatsiooni. Mis kehtib?","Konks näib oma tavapärasest olekust üles painutatud.","Järgmise koormusega painutage deformatsioon tagasi.","Peatage kraana töötamine ja laske konks eksperdil üle kontrollida.","Kinnitage ainult kergeid koormusi ja jätkake tööd.","Deformatsioon võib mõjutada konksu ohutust; edasine omavoliline kasutamine ei ole lubatud."],"k2-zugueberlast":["Koormus on raskem, kui esialgu arvati. Mida sa teed?","Ettevalmistuse käigus tekib uus kaaluinfo.","Asendage ohutusvaru kiirema tõstmisega.","Ignoreeri koorma kaalu, kinnitades selle teise punkti.","Määrake tegelik koormus ja kontrollige uuesti koormuspiiranguid.","Ohutu tõstmine eeldab usaldusväärseid koormusandmeid ja vastavust kõikidele asjakohastele kandevõimetele."],"k2-arbeitskorb":["Kas tavaline kraanakonks kannab inimesi kergesti?","Inimene tahab jõuda kõrgele töökohale.","Ei, reisijatevedu nõuab lubatud erivahendeid ja -meetmeid.","Jah, kui inimene hoiab tropiköiest kinni.","Jah, niipea, kui löök tehakse eriti aeglaselt.","Inimeste vedu on lubatud ainult selleks ettenähtud eritingimustel."],"k2-bruecke":["Sildkraana liigub mööda ühist saali teed. Mis on oluline?","Töötajad jäävad transporditee alla.","Sõitke nii, et koorem on töötajate peade kohal.","Hoidke koormatee ja liiklusala tõhusalt vabad ja turvalised.","Kasutage edasiste meetmete asemel ainult hoiatussignaali.","Ohustatud inimesed ei tohi olla rippuvate koormate all ega oma transporditeel."],"k2-zweitekrane":["Kaks kraanat töötavad kattuval alal. Mis on vajalik?","Poomid või koormad võivad üksteisega kokku põrkuda.","Mõlemad kraanaoperaatorid töötavad korraga ilma eelneva kokkuleppeta.","Liikumisi kiirendatakse teadlikult, et vältida ristmikke.","Koordineerida tegevusi ja võtta asjakohaseid meetmeid vastastikuste ohtude vältimiseks.","Kattuvad tööpiirkonnad nõuavad koordineeritud töökorraldust ja sobivaid kaitsemeetmeid."],"k2-pruefbuch":["Mis tähtsus on kraana kohustuslikul korduval ülevaatusel?","Masinat kasutatakse töös regulaarselt.","See täiendab operatiivjuhtimist ettenähtud ekspertiisiga.","See asendab jäädavalt igasuguse visuaalse kontrolli enne töö algust.","See on vajalik ainult pärast õnnetust.","Korduvatel kontrollidel ja jooksvatel tegevuskontrollidel on erinevad ülesanded."],"k2-absetzflaeche":["Kavandatav paigutusala on ebaühtlane. Kuidas sa käitud?","Koorem võib asetamisel ümber minna.","Asetage koorem ühte nurka ja laske sellel muutumatult rippuda.","Valmistage ette sobivad, kandvad ja stabiilsed alused või pinnad.","Langetamise ajal asetage üks inimene koorma alla.","Paigutamisalad peavad koormat ohutult toetama ja vältima ohtlikke ümberminekuid või veeremisliigutusi."],"k2-anfahrbereich":["Enne kui kraana liikuma hakkab, on sõidualal üks inimene. Mida sa teed?","Marsruut on inimese poolt blokeeritud.","Lükake inimene lühikese proovisõiduga kõrvale.","Ilma visuaalse kontrollita liikuge välja, kasutades ainult piirlülitit.","Alustage liikumist alles siis, kui ohuala on puhas ja ohutu.","Sõitmine ja pööramine ei tohi inimesi ohustada."],"k2-schlaffseil":["Miks ei peaks tõstetross maha asetades kontrollimatult lõdvaks muutuma?","Koormus on peal, konks on veelgi langetatud.","Et köis ja konksud ei jääks kinni ega saaks kontrollimatult koormata.","Et koormat saaks seejärel köiega külgsuunas tõmmata.","Nii et tropid eralduvad konksu küljest.","Kontrollimatu kaablite vedamine võib põhjustada takerdumist ja ohtlikku koorma liikumist."],"k2-pendel":["Veetav koorem hakkab kõikuma. Mis on õige?","Koormus liigub külgsuunas planeeritust rohkem.","Kompenseerige kiirete vastuliigutuste ja täiskiirusega.","Vähendage kontrollitult liigutusi ja rahulikku pendelrännet ilma inimesteta ohualal.","Hoidke kõikuvat koormat paljaste kätega.","Võnkuvad koormused võivad mõjutada inimesi ja rajatisi; rahulikud liigutused vähendavad riski."],"k2-funkakku":["Kraana raadiojuhtimisel on nõrk aku. Mis kehtib?","Ühendus võib tõstmise ajal katkeda.","Tõstke koorem kiiresti üles, enne kui juhtseade ebaõnnestub.","Kui ühendus katkeb, liigutage koormat tropist tõmmates.","Enne kasutamist veenduge, et juhtühendus oleks usaldusväärne.","Usaldusväärne juhtimine ja side on juhitud kraana liikumise eelduseks."],"k2-mehrereanschlaeger":["Kaks inimest annavad korraga kraanajuhile erinevaid signaale. Mis on õige?","Märgid on üksteisega vastuolus.","Katkestage liikumine ja selgitage selget vastutust.","Eelista kaugemal asuva inimese märki.","Jätkake liikumist oma enesetunde järgi.","Kraanajuhid vajavad selget ja ühemõttelist suhtlust, eriti kui koormateed on segased."],"k2-endabschaltung":["Miks ei võiks piirlülitit tavapärase käigupiiranguna kuritarvitada?","Koormust liigutatakse sageli maksimaalse tõstekauguseni.","Lõpplülitid võimaldavad üldiselt kiiremat tõstmist ilma nähtavuseta.","Lõpplülitid on ohutusseadmed ja ei asenda kontrollitud tööd.","Neid tuleks iga löögiga võimalikult tugevalt lüüa.","Ohutusseadmed kaitsevad ohtude eest ja neid ei tohi plaanipäraselt üle kasutada."],"k2-wetterbeobachtung":["Suure pindalakoormuse korral tugevneb tuul oluliselt. Mida nõutakse?","Suur komponentide ala toimib nagu puri.","Tõstke koorem alati kõrgemale, et tuul vähem mõjuks.","Vahetage tropid õhemate vastu.","Hinnake tuule- ja tööpiiranguid ning vajadusel reguleerige tõstejõudu.","Tuul võib tekitada märkimisväärseid lisajõude ja pendli liikumisi, eriti suure pindalaga koormuste korral."],"k2-ortswechsel":["Mis on oluline autokraana uude asukohta kolimisel?","Aluspinnas ja tugitingimused muutuvad.","Enne koorma uuesti ülesvõtmist kontrollige aluse asukohta ja tuge.","Rakendage eelmise asukoha sätteid kontrollimata.","Laske tugi tõstmise ajal uuesti reguleerida.","Igal paigalduskohal võivad olla erinevad maa- ja tugikoormuse tingimused."],"k2-betriebsbereich":["Kraana peaks töötama üle tänava. Mida on vaja selgitada?","Ohualasse võivad sattuda kolmandad isikud.","Kinnitage teed ainult hoiatussignaaliga.","Nõutavad lukustused, hääletamine ja kaitsemeetmed jaoturi ees.","Tõstke koorem võimalikult kiiresti üle sõidukite ilma seda kinnitamata.","Ohutu liikluse marsruutimine hoiab ära koormate ja kraana liikumisega kaasneva riski kolmandatele isikutele."],"k2-hochheben":["Pärast proovitõstuki ripub koorem selgelt viltu. Mis on õige?","Fookus oli ilmselt valesti hinnatud.","Jätkake tõstmist, et tasakaalustamatus paraneks iseenesest.","Laske ühel inimesel kallet koormat tõmmata.","Asetage koorem turvaliselt maha ja kontrollige uuesti kinnitust ja raskuskeset.","Testtõstukit kasutatakse vale kinnituse ja ebastabiilse koormaasendi tuvastamiseks enne transportimist."],"k2-schwebelast":["Kas saate jätta tõstetud koorma järelvalveta rippuma?","Vahetus lõpeb, aga koorem on endiselt konksu otsas.","Ei, langetage koorem ohutult ja kinnitage kraana korralikult.","Jah, kui kraana on eemaldumise vastu lukustatud.","Jah, kuni hoiatussilt maas.","Põhimõtteliselt ei tohiks rippuvaid koormaid järelevalveta jätta."],"k2-mitnahme":["Kolleeg tahab sõita kraanakoormaga. Mis kehtib?","Koormus tuleks transportida kõrgemasse kohta.","Ratsutamine on lubatud, kui kolleeg kannab kiivrit.","Inimesi ei tohi tavaliste koormate peal transportida ega nende külge kinnitada.","Sõit on alati lubatud seni, kuni kolleeg on kraanajuhile teada.","Inimeste kandmine koos koormaga tekitab märkimisväärseid kukkumis- ja muljumisohtu."],"k2-warnsignal":["Kraana töötav hoiatussüsteem ebaõnnestub. Mis on õige?","Enne väljasõitu ei ole enam võimalik hoiatada.","Ignoreeri süsteemi, kui mootor töötab.","Asendage hoiatus jäädavalt, koputades korpust.","Teatage ohutusega seotud rikkest ja katkestage toimingud vastavalt juhistele.","Nõutavad hoiatusseadmed peavad olema töökorras, et inimesed oleksid õigeaegselt kaitstud."],"k2-schneekante":["Autokraanat tuleb külmunud, ebatasasel pinnasel toetada. Mis kehtib?","Muld võib sulades kaotada oma kandevõime.","Hinnake kandevõimet ja tugiolukorda tegelikes tingimustes.","Külmunud pinnasel on alati igasugune kandevõime.","Asetage toed ainult väikestele kividele.","Temperatuur, niiskus ja aluspinna struktuur mõjutavad kraanakohtade kandevõimet."],"k2-laufkatze":["Käru liigub takistuse poole. Kuidas sa käitud?","Sõidualas on objekt.","Lükake objekt koos koormaga aeglaselt eemale.","Lõpetage liikumine õigeaegselt ja laske takistus ohutult eemaldada.","Sõitke suurema kiirusega takistusest mööda.","Kraana liigutusi tuleb juhtida nii, et ei tekiks kokkupõrkeid takistustega."],"k2-anschlagaufnahme":["Koorma peale tuleks võtta selleks ette nähtud aasa abil. Mis on õige?","Aas võiks olla mõeldud ainult katte paigaldamiseks.","Iga aas sobib kraana täiskoormusele.","Laadige aasa ainult kahe inimesega korraga.","Enne kasutamist kontrollige kinnituspunkti kandevõimet ja sobivust.","Mitte iga olemasolev aas ei ole stabiilne kinnituskoht kraanakoormustele."],"l2-seilbruch":["Trossil on näha mitu üksikut katkist traati. Mis on õige?","Katkestuskohad on kandva köie piirkonnas.","Ärge jätkake tõsteseadmete kasutamist ja laske seda professionaalselt hinnata.","Painutage traadi otsad paljaste kätega tagasi.","Kui koormus on eriti väike, jätkake köie kasutamist.","Traadi katkemine võib olla kasutuselt kõrvaldamise kriteerium; Kahjustatud köied tuleb professionaalselt hinnata."],"l2-schaekel":["Mis on köidiku kasutamisel ülioluline?","Säng ühendab troppi ja koormat.","Asendage polt mis tahes naelaga.","Kontrollige sobivat kandevõimet, kahjustamata seisukorda ja õigeid polte.","Hinnake kandevõimet värvi põhjal.","Köidikud peavad olema sobiva suurusega, neid tuleb kasutada täielikult ja ettenähtud laadimissuunas."],"l2-tragfaehigkeit":["Mida peate arvestama mitme kiudude kasutamisel?","Kiud jooksevad vertikaali suhtes nurga all.","Lihtsalt lisage iga ahela kandevõime vastavalt soovile.","Riputage koorem ainult kõige kergemale ahelale.","Võtke arvesse kogu ankru ja nurga tüübi kandevõimet.","Kaldenurk ja kiudude efektiivne arv mõjutavad oluliselt lubatud koormust."],"l2-schweissnaht":["Kas improviseeritud kinnituspunkti saab keevitada koorma külge?","Koorma jaoks ei ole ette nähtud sobivaid pealevõtmispunkte.","Kasutage ainult korralikult projekteeritud ja heakskiidetud kinnituspunkte.","Iga keevisõmblus on katsetamata piisav.","Sisestage konks läbi lehtmetalli avause.","Kinnituspunktid peavad olema tõestatud, et need sobivad tõstmisel kasutatavatele jõududele."],"l2-einseitig":["Koormus on ühelt poolt oluliselt raskem. Kuidas te sellesse suhtute?","Raskuskese asub väljaspool geomeetrilist keskpunkti.","Jätke kõik kiud raskuskeskmest sõltumata sama pikkusega.","Määrake raskuskese ja reguleerige asendit vastavalt.","Esmalt tõstke koorem täiskõrgusele.","Kui raskuskese on tsentrist väljas, võivad koormad ootamatult kaldleda või üksikud kiud võivad olla ülekoormatud."],"l2-kettenriss":["Mis kehtib nähtavate pragudega ketttropi kohta?","Ühes keti lülis on mõra.","Märkige pragu värviga ja tõstke see muutmata kujul.","Mähi link traadiga ja kasuta uuesti.","Eemaldage kett kohe ja teavitage vastutavat isikut.","Praod kandvates ketilülides on ohutuse seisukohalt olulised kahjustused ja nõuavad kasutusest kõrvaldamist."],"l2-lastfuehrung":["Kuidas kanda suurt koormat, kui on pöörlemisoht?","Koorem võib tõstmise ajal küljele välja paiskuda.","Kasutage sobivaid juhtimisseadmeid ja ohutut kaugust.","Hoidke koormat sõidu ajal otse käte vahel.","Astuge koormuse alla ja joondage see altpoolt.","Koorma juhtimine ei tohi põhjustada käte või kehade sattumist ohualasse."],"l2-schnueren":["Mis on pitside kinnitamisel oluline?","Tropp juhitakse ümber komponendi.","Eeldage sama kandevõimet kui mis tahes muud tüüpi ankrutel.","Jälgige kinnituse tüübi sobivust ja lubatud koormust vastavalt märgistusele.","Tõmmake tropid ilma kontrollimata mis tahes määral kokku.","Pitsikinnituse tüüp võib muuta lubatud kandevõimet ja seda tuleb õigesti kasutada."],"l2-winkelmesser":["Miks te ei saa lamedat ahela nurka ignoreerida?","Kaks tropiliini jooksevad koormani peaaegu horisontaalselt.","Lame nurk muudab kiud automaatselt tugevamaks.","Koormus jaotub alati võrdselt olenemata nurgast.","Suured keermejõud võivad ületada lubatud kandevõimet.","Kui nurk vertikaali suhtes suureneb, suurenevad kiudude pinged."],"l2-heisse-last":["Mida on vaja kuuma koorma kontrollimiseks?","Terasest osa on hiljuti kuumtöödeldud.","Jälgige troppide temperatuuripiiranguid ja sobivat valikut.","Iga tekstiiltropp talub mis tahes temperatuuri.","Märgistus ei oma tähtsust, kui see on kuum.","Temperatuur võib mõjutada troppide lubatud kandevõimet."],"l2-abstand":["Kas saate koorma alla pannes sõrmed alla panna?","Koormus peaks maanduma pinnale millimeetri täpsusega.","Jah, kui kannate töökindaid.","Ei, hoidke distantsi ja kasutage sobivaid abivahendeid.","Jah, kui kraana liikumine on eriti aeglane.","Koorma ja aluse vahele jäävad kehaosad võivad kinni jääda."],"l2-verbindung":["Trossiketi ühenduslüli ei ole lukustatud. Mis kehtib?","Kinnitus on puudu.","Kasutage polti ilma lukuta, kui keegi ei vaata.","Kinnitage element kleeplindiga.","Ärge lööge enne, kui kinnitus on korralikult kinnitatud.","Ühenduselemendid peavad olema täielikult kinnitatud ja vastavalt nende konstruktsioonile."],"l2-lasthaken":["Mida kontrollite kraana konksu otsas rippudes?","Konksu sisse tuleks juhtida mitu troppi.","Tagada konksude ja vedrustuse kindel sobivus ja sobivus.","Asetage tropid konksu otsa.","Asendage konksulukk kaablisidemega.","Jõudu tuleb rakendada ettenähtud piirkondades."],"l2-fasern":["Tõsterihm näitab tugevat karedust ja kiukahjustusi. Mis on õige?","Tugikiud on nähtavalt kahjustatud.","Katke kahjustus teise sõlmega.","Eraldage tõsterihm ja laske seda spetsialistil kontrollida.","Seejärel tõstke koorem kiiremini üles.","Kahjustatud kandvad kiud võivad oluliselt vähendada tõsterihma kandevõimet."],"l2-anheben":["Mis kehtib kohe pärast esimest tõstesentimeetrit?","Koorem tõuseb just aluselt.","Tõmmake koorem ilma kontrollita täiskõrgusele.","Kontrollige koorma all, kas tropid on pingutatud.","Kontrollige peatuse asendit, tasakaalu ja liikumiskäitumist.","Kontrollitud testtõstuk muudab võimalikud ebastabiilsused nähtavaks enne edasist transporti."],"l2-lastgewichte":["Koorma kaal pole teada. Mis on õige?","Komponendil puudub kaalumärgistus.","Enne troppide valimist määrake koormatav kaal.","Hinnake kaalu koormuse värvi alusel.","Kasutage mis tahes kahekordse pikkusega troppi.","Ilma teadaoleva või usaldusväärselt määratud kaaluta ei saa troppide sobivust kindlalt kontrollida."],"l2-lose-teile":["Tõstataval koormal on lahtised tööriistad. Mida sa teed?","Tõstmisel võivad tööriistad maha kukkuda.","Hoidke sõidu ajal tööriistu ühe käega.","Enne tõstmist eemaldage või kinnitage tõhusalt lahtised esemed.","Tõstke koormust veidi kiiremini, et miski ei libiseks.","Lahtised esemed võivad kukkuda ja ohustada piirkonnas viibivaid inimesi."],"l2-wind":["Tugeva tuulega kinnitatakse suur koorem. Mis kehtib?","Komponent pakub tuulele ründamiseks suurt pinda.","Tõstke koormust, arvestamata õõtsuvaid liigutusi.","Täiendavad inimesed peaksid koormat otse hoidma.","Hinnake tuuleolusid ja hoiduge tõstmisest, kui olukord pole ohutu.","Tuulejõud võivad mõjutada koorma juhtimist ja stabiilsust transpordi ajal."],"l2-unterlage":["Miks on võõrutamisel olulised sobivad dokumendid?","Ümmargune koorem veereks maapinnal minema.","Asetage koorem kindlalt alla ja kindlustage see vajadusel veeremise vastu.","Jätke koorem otse troppidele.","Lükake dokumendid koorma alla alles pärast nende mahapanekut.","Sobivad toed hoiavad ära ümbermineku ja soovimatud liigutused mahalaskmisel."],"l2-transportweg":["Mida tuleb enne koorma transportimist kooskõlastada?","Koormust liigutatakse üle mitme tööpiirkonna.","Just rummu eeldatav kestus.","Ohutu koormatee, side ja vajalikud tõkked.","Koorma all peaks teed näitama üks inimene.","Koormate transport eeldab ohutuid liikumisteid ja selget koordinatsiooni."],"l2-schutzschlauch":["Millele tuleks tähelepanu pöörata kaitsevoolikuga troppide kasutamisel?","Vastu karmi serva lebab riba.","Iga õhuke riidelapp asendab sobivat servakaitset.","Kaitsevoolik eemaldab kõik lubatud koormuspiirangud.","Valige kaitsevahendid vastavalt sobivusele ja kasutusnõuetele.","Kaitsevahendid peavad vastama materjalile, servale ja ettenähtud koormusele."],"l2-reinigung":["Tõsterihm oli saastunud tundmatu kemikaaliga. Mis on õige?","Lint ei saa enam selgelt hinnata.","Lõpetage kasutamine ja selgitage sobivust või seisukorda professionaalselt.","Puhastage mis tahes lahustiga ja jätkake kohe tõstmist.","Ignoreerige kemikaali, kui lint on kuiv.","Kemikaalid võivad mõjutada tekstiiltroppide tugevust."],"l2-aufhaengung":["Mida kontrollite, kas vedrustuslingil on mitu kiudu?","Kaks kiudu asetatakse kokku suspensioonis.","Niit võib soovi korral konksu otsa liikuda.","Kõik ühenduselemendid peavad olema sobivad ja paigutatud ettenähtud viisil.","Praguga rõngast saab kasutada väikeste koormuste korral.","Peatus- ja ühenduselemendid peavad olema kandvad ja õigesti paigutatud."],"l2-einweiserrolle":["Mis kehtib juhul, kui ründajal ja kraanaoperaatoril puudub vaateväli?","Kandur blokeerib vaate langetuspunktile.","Koordineerige, helistades mitmele inimesele ilma vastutuseta.","Liigutage koormust müra alusel ilma juhisteta.","Korraldage selge ja turvaline suhtlus ja peatage see, kui see on ebaselge.","Nähtavuse puudumist tuleb kompenseerida tõhusa koordineerimise ja turvalise suhtlusega."],"l2-ausserbetrieb":["Kahjustatud tropp sai korda tehtud. Mis veel oluline on?","See jääb vabalt ligipääsetavaks koos kasutusvalmis ressurssidega.","Kindlustage edasise juhusliku kasutamise eest ja teavitage vastutavat isikut.","Tagastage toode märgistamata laoseisu.","Kasutage seda uuesti ainult eriti kerge koorma kandmisel.","Kasutuselt kõrvaldatud tropid tuleb enne edasist kasutamist usaldusväärselt kaitsta."],"b2-schwenkradius":["Miks on ekskavaatori tagumine pöörderaadius kriitiline?","Saba liigub üle piiratud tööpiirkonna.","Kolmandaid isikuid võib püüda kõikuv pealisehitus.","Pöörderaadius ei mõjuta masina kõrval viibivaid inimesi.","Tagaosa liigub alati ainult sõidusuunas.","Pööramisel tekib ohuala ka masina taha."],"b2-verkehrseinweiser":["Kuidas tagatakse sõiduliikumine, kui nähtavus on varjatud?","Ekskavaator peab manööverdama takistuse taga.","Sõitke signaalija signaale nägemata.","Vajadusel korraldada asjakohane juhendamine selge suhtlusega.","Kindlustage tagurdamine ainult ühe korra helinaga.","Segased marsruudid nõuavad tõhusaid meetmeid kokkupõrgete ja kinnijäämise vältimiseks."],"b2-standplatz":["Mis kehtib kallakul asuva ekskavaatoristendi kohta?","Põrand on kaldu ja võib olla libe.","Masin võib ulatuda nii kaugele, kui soovib mis tahes kalde korral.","Paigaldage ekskavaator alati lahtisele mullakihile.","Enne kasutamist kontrollige masina stabiilsust ja tööpiire.","Kallaku kalle ja aluspinnas mõjutavad oluliselt stabiilsust."],"b2-oberleitung":["Miks on vaja planeerida poomi kaugust elektriliinidest?","Pööramisel võib nool kaabli lähedale tulla.","Elektriline välklamp on võimalik ka ilma otsese kontaktita.","Elektrit juhib ainult kopp, mitte poom.","Kuiva pinnasega on iga vahemaa automaatselt ohutu.","Enne elektrisüsteemidele lähenemist tuleb selgeks teha kasutuspiirangud ja kaitsekaugused."],"b2-fremdperson":["Möödakäija siseneb ehitusplatsile panoraamalasse. Mis on õige?","Inimene seisab ootamatult ekskavaatori kopa lähedal.","Tõstke labidas üles ja keerake see üle inimese.","Lõpetage kohe liikumine ja laske ala puhastada.","Jätkake lihtsalt inimese jälgimist külgaknast.","Ohualas viibivaid inimesi ei tohi tööliigutused ohustada."],"b2-parkstellung":["Kuidas kindlustatakse mullateisaldusmasin pärast töö lõpetamist?","Ekskavaator jääb ehitusplatsile järelevalveta.","Jätke lusikas pea kõrgusele.","Laske mootoril järelevalveta töötada.","Pange töövahendid maha, kinnitage masin ja vältige volitamata kasutamist.","Õige parkimine vähendab juhuslikku liikumist ja volitamata juurdepääsu."],"b2-eigenlast":["Miks on varustuspiirangud ekskavaatoriga tõstmisel üliolulised?","Poomile tuleb peale võtta raske koorem.","Vastasel juhul võib stabiilsus ja lubatud kandevõime ületada.","Iga masin suudab tõsta mis tahes koormat seni, kuni kopp mahub.","Riski määrab ainult trossi pikkus.","Teave tõste- ja kandevõime kohta sõltub seadmest ja kasutusolukorrast."],"b2-untergrundhohlraum":["Vana keldri kohal võiks põrand olla auklik. Mida sa teed?","Peaksite sõitma ekskavaatoriga piirkonda.","Ületage koht maksimaalse hooga.","Enne edasi sõitmist tehke kindlaks kandevõime ja võimalikud õõnsused.","Lihtsalt asetage pinnale raske koormus.","Õõnsused võivad masina raskuse all kokku vajuda ja põhjustada masina avarii."],"b2-feuchtigkeit":["Pärast tugevat vihma muutub muldkeha pehmeks. Mis on õige?","Muldkeha serva lähedal töötab ekskavaator.","Haardeulatuse suurendamiseks liigutage masin servale lähemale.","Ignoreeri muudatusi kuni vahetuse lõpuni.","Hinnake uuesti pinnase ja stabiilsuse tingimusi.","Niiskuse tungimine võib muuta muldkehade kandevõimet ja stabiilsust."],"b2-bodenprobe":["Miks tuleb torujuhtme plaane enne kaevamist kontrollida?","Kaablid võiksid kulgeda planeeritud kaevetööde all.","Et saaks liinid tuvastada ja sobivaid turvameetmeid planeerida.","Nii et kaevetöid saab teostada kiiremini, sõltumatult kolmandate osapoolte süsteemidest.","Kuna masinaid ei tohi kunagi kasutada kaablite läheduses.","Maa-alused toiteliinid nõuavad enne kaevetöid usaldusväärse asukoha selgitamist."],"b2-maschinenzugang":["Mis kehtib mullateisaldusmasinasse sisenemisel ja sealt väljumisel?","Masin on ebatasasel maastikul.","Libistage hüdrovoolik kabiinist alla.","Kasutage selleks ettenähtud samme ja tagage kindel tugi.","Hüpake masina töötamise ajal pöörlevale hoovale.","Ohutu tõus ja sobivad peatumispunktid vähendavad kukkumise ja muljumise ohtu."],"b2-kupplung":["Kuidas kontrollida uut ekskavaatorit pärast paigaldamist?","Kopp ühendatakse kiirliitmiku kaudu.","Hinda lusikat visuaalselt ainult suurema vahemaa tagant.","Astu otse tõstetud lusika alla.","Tagada õige lukustamine ja ettenähtud juhtimisetapid.","Valesti lukustatud kinnitused võivad lahti tulla ja inimesi ohustada."],"b2-hydraulikwartung":["Miks ei tohi surve all hüdrovoolikuid avada?","Voolik tuleb vahetada.","Väljavoolav vedelik võib kõrge rõhu tõttu põhjustada tõsiseid vigastusi.","Rõhk takistab alati õli väljapääsu.","Avatud liini saab ohutult oma kätega kontrollida.","Kõrgsurvevedelik võib tungida kudedesse ja nõuab ohutut rõhu vähendamist."],"b2-fahrweg":["Tuleb sõita üle ajutise ehitussilla. Mida sa kontrollid?","Sild on ette nähtud ainult teatud koormuste jaoks.","Kas silla värv sobib masinaga.","Kandevõime ja sobivus masina kaalule ja mõõtmetele.","Ainult seda, kas kerge auto on juba sillal sõitnud.","Ajutisi konstruktsioone tohib kasutada ainult nende tõendatud kandevõime piires."],"b2-baggertransport":["Mis on oluline madallaaduriga ekskavaatori transportimisel?","Masin viiakse järgmisele ehitusplatsile.","Laske töövahenditel lõdvalt üle serva välja ulatuda.","Hoidke kabiini uks sõidu ajal lahti.","Kinnitage masin vastavalt transpordispetsifikatsioonidele ja kontrollige laadimisseadmeid.","Transpordilukud ja sobivad laadimisvõimalused hoiavad ära libisemise ja kukkumise."],"b2-schaufelfuellung":["Miks rataslaadur ei tohi kõrgele tõstetud kopaga kiiresti sõita?","Koormus on raske ja maapind ebatasane.","Kõrge raskuskese võib suurendada ümbermineku ohtu ja nähtavusprobleeme.","Kopp stabiliseerub suurel kiirusel automaatselt.","Labida kõrgus ei ole stabiilsuse seisukohalt oluline.","Kõrgendatud raskuskese halvendab tavaliselt stabiilsust sõitmisel ja kurvides."],"b2-fussgaenger":["Kuidas käitute jalakäijate kõrval manööverdades?","Juurdepääs ehitusplatsile on ka jalgtee.","Kasutage labidat, et suunata jalakäijad küljele.","Liikuge ainult siis, kui ala on ohutult vaba ja juhitav.","Lihtsalt mürake üks kord ja sõitke aeglaselt ilma nähtavuseta edasi.","Sõidukite ja reisijate liiklus peab olema tõhusalt eraldatud või ohutult kooskõlastatud."],"b2-ueberlastwarnung":["Tõstmisel teatab masin ülekoormusest. Mida sa teed?","Tõstetud koorem saavutab lubatud piirid.","Lülitage hoiatus välja ja jätkake selle tõstmist muutmata kujul.","Pingutage masina töötamise ajal koormust järsult.","Peatage ohtlikud liigutused ja parandage ohutult koorma olukord.","Ülekoormuse hoiatused viitavad võimalikele piirangute rikkumistele ja stabiilsusriskidele."],"b2-wasserleitung":["Kaevamisel tuleb tundmatu toru katmata. Mis kehtib?","Ehitusplaanides joont ei näidata.","Lõpetage töötamine kahjustatud piirkonnas ja laske liin professionaalselt tuvastada.","Proovige liini liigutada ekskavaatori labidaga.","Jätkake kaevamist otse liini all ilma kontrollimata.","Tundmatud liinid võivad põhjustada elektri-, gaasi- või veeohtu."],"b2-hangefahrt":["Kuidas juhtida ekskavaatorit järsul kallakul?","Planeeritud trass kulgeb mööda nõlva.","Sõitke üle kallaku sõltumata tootja piirangutest.","Järgige masina lubatud kallet ja ettenähtud sõidustiili.","Sõiduki tasakaalustamiseks keerake nool kaugele välja.","Lubatud kalle oleneb masinast, pinnast ja tootja infost."],"b2-schlechtebeleuchtung":["Pimedas süvendis töötades on nähtavus ebapiisav. Mis on õige?","Inimesi ja takistusi ei näe peaaegu üldse.","Toimingu kiireks lõpuleviimiseks suurendage kaevamiskiirust.","Ärge kasutage tulesid, kui mootor töötab.","Peatage töö, kuni ohualad on piisavalt nähtavad.","Kontrollitud masina liikumiseks on vajalik sõidu- ja tööalade ohutu nähtavus."],"b2-kettenverschleiss":["Igapäevasel kontrollil märgatakse kahjustatud röövikurada. Mida sa teed?","Kettühendus näitab selgeid kahjustusi.","Ärge jätkake masina kontrollimatut kasutamist ja teatage kahjustustest.","Jätkake suurel kiirusel sõitmist, et kett sirguks.","Jätkake tööd ainult pehmel pinnasel ilma kontrollimata.","Ajami kahjustused võivad halvendada juhitavust ja stabiilsust."],"b2-ladearbeiten":["Laadite ekskavaatoriga veoauto. Mis on oluline?","Tõstukijuht jääb laadimisala lähedale.","Pöörake kopp üle kaitsmata juhikabiini.","Vältida inimeste viibimist ohupiirkonnas ja koordineerida protsesse.","Alustage laadimist ilma juhiga suhtlemata.","Laadimisel on oht materjali mahakukkumiseks ja õõtsumiseks."],"b2-arbeitsunterbrechung":["Te katkestate kaevetööd koosolekuks. Mis kehtib?","Masin peaks seisma mitu minutit ilma seda kasutamata.","Tõstetud labidas jäta markeriks.","Jätke masin sisselülitatud veoajamiga järelevalveta.","Asetage seade ohutult maha ja kindlustage masin tahtmatu kasutamise vastu.","Isegi lühikesed katkestused nõuavad masina ohutut seisundit."],"b2-rollmaterial":["Lahtine materjal võib rataslaaduriga transportimisel maha kukkuda. Mis on õige?","Laadur sõidab töötajatele lähedale.","Tõstke koorem turvaliselt üles ja valige ohutu sõidustiil koos sobiva labidaasendiga.","Tõstke labidas nii kõrgele kui võimalik, et ümbritsevale alale oleks selge vaade.","Tõstke koorem üles ilma ämbri täitmist piiramata.","Lahtised koormad, kõrged kopaasendid ja halb nähtavus võivad ohustada inimesi ja liiklust."]};
